private TreeNode<T> rotateRight(TreeNode<T> node){
    if (node == null) {
        return null;
    }
    TreeNode<T> leftChild = node.left;
    if (leftChild == null) {
        // Nothing to rotate
        return node;
    }

    // Move left child's right subtree to node's left subtree
    node.left = leftChild.right;
    if (leftChild.right != null) {
        leftChild.right.parent = node;
    }

    // Perform rotation
    leftChild.right = node;

    // Update parent references
    leftChild.parent = node.parent;
    if (node.parent == null) {
        // node was root; after rotation, leftChild becomes the new root
        // Caller should update the tree root reference as needed
    } else if (node.parent.left == node) {
        node.parent.left = leftChild;
    } else {
        node.parent.right = leftChild;
    }

    node.parent = leftChild;

    return leftChild;
}

private TreeNode<T> rotateRight(TreeNode<T> node) {
    if (node == null) return null;

    TreeNode<T> left = node.left;
    if (left == null) return node;   // nothing to rotate

    TreeNode<T> rightOfLeft = left.right;

    // Rotate
    left.right = node;
    node.left = rightOfLeft;

    // Update parent links
    TreeNode<T> parent = node.parent;
    left.parent = parent;
    node.parent = left;
    if (rightOfLeft != null) {
        rightOfLeft.parent = node;
    }

    // Adjust the parent's child pointer if necessary
    if (parent != null) {
        if (parent.left == node) {
            parent.left = left;
        } else if (parent.right == node) {
            parent.right = left;
        }
    }

    return left;
}

private TreeNode<T> rotateRight(TreeNode<T> node){
    // If the node is null or has no left child, rotation is not possible.
    if (node == null || node.getLeft() == null) {
        return node;
    }
    TreeNode<T> leftChild = node.getLeft();

    // Perform rotation:
    // 1. The left child's right subtree becomes the node's left subtree
    node.setLeft(leftChild.getRight());

    // 2. The node becomes the right child of its former left child
    leftChild.setRight(node);

    // The left child is now the new parent of the node
    return leftChild;
}

private TreeNode<T> rotateRight(TreeNode<T> node) {
    if (node == null) {
        return null;
    }

    TreeNode<T> left = node.getLeft();
    if (left == null) {
        // Cannot rotate right if there is no left child.
        return node;
    }

    TreeNode<T> parent = node.getParent();
    TreeNode<T> leftRight = left.getRight();

    // Reattach the left subtree's right child to the node.
    node.setLeft(leftRight);
    if (leftRight != null) {
        leftRight.setParent(node);
    }

    // Move node to the right of the left child.
    left.setRight(node);
    node.setParent(left);

    // Attach the left child to the original parent of the node.
    left.setParent(parent);
    if (parent != null) {
        if (parent.getLeft() == node) {
            parent.setLeft(left);
        } else if (parent.getRight() == node) {
            parent.setRight(left);
        }
    }

    return left;
}

private TreeNode<T> rotateRight(TreeNode<T> node) {
    // If node is null or has no left child, rotation cannot be performed
    if (node == null || node.left == null) {
        return node;
    }

    // The left child becomes the new root of this subtree
    TreeNode<T> left = node.left;
    TreeNode<T> leftRight = left.right;

    // Perform rotation
    left.right = node;
    node.left = leftRight;

    // Update parent references for the involved nodes
    left.parent = node.parent;
    node.parent = left;
    if (leftRight != null) {
        leftRight.parent = node;
    }

    // If the original node had a parent, update its child reference
    if (left.parent != null) {
        if (left.parent.left == node) {
            left.parent.left = left;
        } else {
            left.parent.right = left;
        }
    }

    // The new root of this rotated subtree is 'left'
    return left;
}

