public String format(LoggingEvent event) {
    if (event == null) {
        throw new IllegalArgumentException("LoggingEvent cannot be null");
    }
    try {
        // If the event provides a pre-rendered message, use that.
        // In many logging frameworks (Log4j, Logback), RenderingEvent has a method getRenderedMessage()
        // that returns a nicely formatted string for the event.
        // If that method does not exist, fall back to the event's message string.
        try {
            java.lang.reflect.Method m = event.getClass().getMethod("getRenderedMessage");
            Object result = m.invoke(event);
            if (result instanceof String) {
                return (String) result;
            }
        } catch (NoSuchMethodException | IllegalAccessException | java.lang.reflect.InvocationTargetException ignored) {
            // ignore and fallback
        }
        // Fallback: use event's message, converting it to a string.
        Object msg = event.getMessage();
        return msg != null ? msg.toString() : "";
    } catch (Throwable t) {
        // In case of any unexpected exception, return an empty string or a friendly message.
        return "";
    }
}

public String format(LoggingEvent event){
    // Guard against null arguments
    if (event == null) {
        return "";
    }
    // The pattern is assumed to be a field defined in the surrounding class.
    // If no pattern is defined, fallback to the event's rendered message.
    String pattern = this.pattern; // field that must exist in the containing class.
    if (pattern == null || pattern.isEmpty()) {
        return event.getRenderedMessage();
    }
    StringBuilder sb = new StringBuilder();
    int i = 0;
    int length = pattern.length();
    while (i < length) {
        char ch = pattern.charAt(i);
        if (ch == '%' && (i + 1) < length) {
            char next = pattern.charAt(i + 1);
            // Escaped percent
            if (next == '%') {
                sb.append('%');
                i += 2;
                continue;
            }
            // Date conversion
            if (next == 'd') {
                i += 2;
                String dateFormat = "yyyy-MM-dd HH:mm:ss.SSS";
                if (i < length && pattern.charAt(i) == '{') {
                    int endBrace = pattern.indexOf('}', i);
                    if (endBrace != -1) {
                        dateFormat = pattern.substring(i + 1, endBrace);
                        i = endBrace + 1;
                    } else {
                        // Malformed, treat as literal
                        sb.append("%d");
                        continue;
                    }
                }
                try {
                    java.text.SimpleDateFormat sdf = new java.text.SimpleDateFormat(dateFormat);
                    java.util.Date date = new java.util.Date(event.getTimeStamp());
                    sb.append(sdf.format(date));
                } catch (Exception e) {
                    // If date formatting fails, fall back to timestamp
                    sb.append(event.getTimeStamp());
                }
                continue;
            }
            // Thread conversion
            if (next == 't') {
                sb.append(event.getThreadName());
                i += 2;
                continue;
            }
            // Level conversion
            if (next == 'p') {
                sb.append(event.getLevel() == null ? "UNKNOWN" : event.getLevel().toString());
                i += 2;
                continue;
            }
            // Logger name conversion
            if (next == 'c') {
                sb.append(event.getLoggerName());
                i += 2;
                continue;
            }
            // Message conversion
            if (next == 'm') {
                sb.append(event.getRenderedMessage());
                i += 2;
                continue;
            }
            // New line conversion
            if (next == 'n') {
                sb.append(System.lineSeparator());
                i += 2;
                continue;
            }
            // Unknown conversion specifier: treat as literal
            sb.append('%').append(next);
            i += 2;
            continue;
        } else {
            sb.append(ch);
            i++;
        }
    }
    return sb.toString();
}

