    int start = end;
    if (start < 0) {
        start = 0;
    }
    if (start > headerPart.length()) {
        start = headerPart.length();
    }

    // Search for the CRLF sequence
    int crlfIndex = headerPart.indexOf("\r\n", start);
    if (crlfIndex == -1) {
        throw new IllegalArgumentException("End of line sequence (\\r\\n) not found in headerPart");
    }
