    int len = headerPart.length();
    for (int i = end; i < len - 1; i++) {
        if (headerPart.charAt(i) == '\r' && headerPart.charAt(i + 1) == '\n') {
            // Return the index of the character after the CRLF sequence
            return i + 1;
        }
    }
    // If we reached the end of the string without finding CRLF
    return -1;
}

