public static void forceDeleteOnExit(File file) throws IOException {
    if (file == null) {
        throw new NullPointerException("file must not be null");
    }
    try {
        Runtime.getRuntime().addShutdownHook(new Thread(() -> {
            try {
                deleteRecursively(file);
            } catch (IOException ignored) {
                // Deletion failure is ignored during shutdown
            }
        }));
    } catch (SecurityException e) {
        throw new IOException("Failed to register shutdown hook", e);
    }
}

private static void deleteRecursively(File f) throws IOException {
    if (f.isDirectory()) {
        File[] children = f.listFiles();
        if (children != null) {
            for (File child : children) {
                deleteRecursively(child);
            }
        }
    }
    if (f.exists() && !f.delete()) {
        throw new IOException("Failed to delete file or directory: " + f);
    }
}

public static void forceDeleteOnExit(java.io.File file) throws java.io.IOException {
    if (file == null) {
        throw new NullPointerException("file must not be null");
    }
    java.util.Deque<java.io.File> stack = new java.util.ArrayDeque<>();
    stack.push(file);
    while (!stack.isEmpty()) {
        java.io.File current = stack.pop();
        if (current == null) {
            continue;
        }
        if (current.isDirectory()) {
            java.io.File[] children = current.listFiles();
            if (children != null) {
                for (java.io.File child : children) {
                    stack.push(child);
                }
            }
        }
        try {
            current.deleteOnExit();
        } catch (SecurityException e) {
            throw new java.io.IOException("Could not register file for deletion on exit: " + current, e);
        }
    }
}

public static void forceDeleteOnExit(File file) throws IOException {
    if (file == null) {
        throw new NullPointerException("File must not be null");
    }

    if (file.isDirectory()) {
        File[] children = file.listFiles();
        if (children == null) {
            throw new IOException("Failed to list contents of directory: " + file);
        }
        for (File child : children) {
            forceDeleteOnExit(child);
        }
    }

    try {
        file.deleteOnExit();
    } catch (SecurityException e) {
        throw new IOException("Unable to schedule deletion for file on exit: " + file, e);
    }
}

public static void forceDeleteOnExit(File file) throws IOException {
    if (file == null) {
        throw new NullPointerException("File must not be null");
    }
    // If the file doesn't exist, nothing to schedule.
    if (!file.exists()) {
        return;
    }
    // If directory, recursively schedule children first.
    if (file.isDirectory()) {
        File[] children = file.listFiles();
        if (children == null) {
            // listFiles can return null if an I/O error occurs.
            throw new IOException("Failed to list contents of directory: " + file);
        }
        for (File child : children) {
            // Recursive call to handle nested directories/files.
            forceDeleteOnExit(child);
        }
    }
    // Finally schedule the file/directory itself for deletion on exit.
    file.deleteOnExit();
}

public static void forceDeleteOnExit(File file) throws IOException {
    if (file == null) {
        throw new NullPointerException("File must not be null");
    }
    // If the file does not exist we still treat it as a success because deleteOnExit
    // would simply ignore it. But to follow the contract of throwing IOException
    // if deletion is unsuccessful, we consider a non-existent file as a failure.
    if (!file.exists()) {
        throw new IOException("File does not exist: " + file);
    }

    // Recursive helper to schedule deletion in post‑order (leaves first)
    Deque<File> stack = new ArrayDeque<>();
    stack.push(file);
    // Use a stack to process directories after their contents
    while (!stack.isEmpty()) {
        File current = stack.pop();
        if (current.isDirectory()) {
            File[] children = current.listFiles();
            if (children == null) {
                // listFiles returning null indicates an I/O error or permission issue
                throw new IOException("Cannot read directory: " + current);
            }
            // Push the directory back onto the stack to delete it after its children
            stack.push(current);
            // Push children onto the stack; they will be processed before the directory
            for (File child : children) {
                stack.push(child);
            }
        } else {
            // Regular file, just schedule deletion
            current.deleteOnExit();
        }
    }

    // After the loop all directories are still on the stack in pre‑order.
    // Process remaining directories to schedule their deletion.
    while (!stack.isEmpty()) {
        File dir = stack.pop();
        if (dir.isDirectory()) {
            dir.deleteOnExit();
        }
    }
}

