            // Avoid adding duplicate edges in undirected graphs
            if (target.getEdge(u, v) == null && target.getEdge(v, u) == null) {
                target.addEdge(u, v);
            }
        }
    }
}

@Override
public void generateGraph(Graph<V, E> target, Map<String, V> resultMap) {
    // Clear any existing vertices and edges from the target graph
    try {
        target.removeAllEdges(new HashSet<>(target.edgeSet()));
        target.removeAllVertices(new HashSet<>(target.vertexSet()));
    } catch (Exception ignored) {
        // If the graph implementation does not support removal, ignore and proceed
    }

    // Define sizes for the two bipartition sets
    final int leftSize = 3;
    final int rightSize = 3;

    List<V> leftPart = new ArrayList<>();
    List<V> rightPart = new ArrayList<>();

    try {
        // Create left partition vertices
        for (int i = 0; i < leftSize; i++) {
            String name = "U" + i;
            @SuppressWarnings("unchecked")
            V vertex = (V) name;
            if (!target.containsVertex(vertex)) {
                target.addVertex(vertex);
            }
            leftPart.add(vertex);
            resultMap.put(name, vertex);
        }

        // Create right partition vertices
        for (int i = 0; i < rightSize; i++) {
            String name = "V" + i;
            @SuppressWarnings("unchecked")
            V vertex = (V) name;
            if (!target.containsVertex(vertex)) {
                target.addVertex(vertex);
            }
            rightPart.add(vertex);
            resultMap.put(name, vertex);
        }

        // Connect every vertex from the left partition to every vertex in the right partition
        for (V u : leftPart) {
            for (V v : rightPart) {
                target.addEdge(u, v);
            }
        }
    } catch (ClassCastException e) {
        throw new IllegalArgumentException(
                "Vertex type V must be String (or convertible) for bipartite graph generation.", e);
    } catch (Exception e) {
        throw new IllegalArgumentException(
                "Failed to generate complete bipartite graph.", e);
    }
}

