/** Helper method to write a varint32 to an OutputStream. */
private static void writeVarint32(OutputStream out, int value) throws IOException {
    while ((value & 0xFFFFFF80) != 0L) {
        out.write((value & 0x7F) | 0x80);
        value >>>= 7;
    }
    out.write(value);
}

public static <T> int writeDelimitedTo(OutputStream out, T message, Schema<T> schema, LinkedBuffer buffer) throws IOException {
    // Validate inputs
    if (out == null) {
        throw new NullPointerException("OutputStream cannot be null");
    }
    if (schema == null) {
        throw new NullPointerException("Schema cannot be null");
    }
    if (message == null) {
        throw new NullPointerException("Message cannot be null");
    }

    // Determine serialized size (in bytes). The Schema interface usually provides this.
    int size;
    try {
        long tmp = schema.getSerializedSize(message);
        if (tmp > Integer.MAX_VALUE) {
            throw new IllegalStateException("Serialized size exceeds Integer.MAX_VALUE");
        }
        size = (int) tmp;
    } catch (Exception e) {
        throw new IOException("Failed to compute serialized size", e);
    }

    // Write the length prefix as a varint
    CodedOutputStream cos = CodedOutputStream.newInstance(out, 4096);
    try {
        cos.writeUInt32NoTag(size);
        // Serialize the message into the CodedOutputStream
        schema.writeTo(message, cos);
        cos.flush();
    } catch (IOException ioe) {
        throw ioe; // Propagate any IO exception from serialization
    } catch (Exception e) {
        throw new IOException("Serialization failed", e);
    }

    // Return the size of the serialized message body (not including the length prefix)
    return size;
}

public static <T> int writeDelimitedTo(OutputStream out, T message, Schema<T> schema, LinkedBuffer buffer) throws IOException {
