    }

    // Compute the serialized size of the message.
    int size = schema.getSerializedSize(message);
    if (size < 0) {
        throw new IOException("Negative size computed for the message");
    }

    // Write the size as a varint32 prefix.
    CodedOutputStream cos = CodedOutputStream.newInstance(out);
    cos.writeRawVarint32(size);

    // Serialize the message directly to the OutputStream.
    schema.writeTo(message, cos);
    cos.flush();

    return size;
}

public static <T> int writeDelimitedTo(OutputStream out, T message, Schema<T> schema, LinkedBuffer buffer) throws IOException {
    if (out == null) {
        throw new NullPointerException("OutputStream cannot be null");
    }
    if (schema == null) {
        throw new NullPointerException("Schema cannot be null");
    }
    // Serialize the message into a temporary byte array first.
    ByteArrayOutputStream temp = new ByteArrayOutputStream();
    schema.writeTo(message, temp);
    int msgSize = temp.size();

    // Write the size as a varint
    while (msgSize > 0x7F) {
        out.write((msgSize & 0x7F) | 0x80);
        msgSize >>>= 7;
    }
    out.write(msgSize);

    // Write the actual message bytes
    temp.writeTo(out);
    return msgSize;
}

