public Mappings diffStructure(String tableName, Mappings mappings) {
    if (mappings == null) {
        return null;
    }
    try {
        // Attempt to retrieve the properties map via reflection
        java.lang.reflect.Method getProps = mappings.getClass().getMethod("getProperties");
        Object propsObj = getProps.invoke(mappings);
        if (!(propsObj instanceof java.util.Map)) {
            throw new IllegalStateException("Mappings does not expose a Map of properties");
        }
        @SuppressWarnings("unchecked")
        java.util.Map<String, Object> props = (java.util.Map<String, Object>) propsObj;

        // Build a new map of properties, excluding the _source field
        java.util.Map<String, Object> diffProps = new java.util.LinkedHashMap<>();
        for (java.util.Map.Entry<String, Object> entry : props.entrySet()) {
            if (!"_source".equals(entry.getKey())) {
                diffProps.put(entry.getKey(), entry.getValue());
            }
        }

        // Try to construct a new Mappings instance using a constructor that accepts a Map
        try {
            java.lang.reflect.Constructor<Mappings> ctor = mappings.getClass().getConstructor(java.util.Map.class);
            return ctor.newInstance(diffProps);
        } catch (NoSuchMethodException nsme) {
            // If no such constructor, attempt to modify the existing instance
            try {
                java.lang.reflect.Method setProps = mappings.getClass().getMethod("setProperties", java.util.Map.class);
                setProps.invoke(mappings, diffProps);
                return mappings;
            } catch (Exception inner) {
                throw new RuntimeException("Mappings instance cannot be modified directly", inner);
            }
        }
    } catch (Exception e) {
        throw new RuntimeException("Failed to diff structure for table " + tableName, e);
    }
}

public Mappings diffStructure(String tableName, Mappings mappings){
    // Defensive checks
    if (mappings == null) {
        return new Mappings();
    }
    // Retrieve the underlying mapping representation.
    // Expect the Mappings type to expose the mapping as a Map via getMapping().
    Map<String, Object> original;
    try {
        original = mappings.getMapping();
    } catch (NoSuchMethodError | IllegalAccessException | IllegalArgumentException | java.lang.reflect.InvocationTargetException exc) {
        // If the expected method is not present, fall back to an empty mapping.
        return new Mappings();
    }
    if (original == null || original.isEmpty()) {
        return new Mappings();
    }
    // Build a new map containing all entries except "_source".
    Map<String, Object> filtered = new java.util.HashMap<>();
    for (Map.Entry<String, Object> entry : original.entrySet()) {
        if ("_source".equals(entry.getKey())) {
            // Skip __source to avoid update conflict.
            continue;
        }
        filtered.put(entry.getKey(), entry.getValue());
    }
    // Return a new Mappings instance containing only the filtered entries.
    return new Mappings(filtered);
}

