public static void createConfigurationDirectory(){
    String osName = System.getProperty("os.name");
    String osVersion = System.getProperty("os.version");
    java.io.File baseDir;
    if (osName != null && osName.toLowerCase(java.util.Locale.ROOT).contains("windows") &&
        osVersion != null && osVersion.startsWith("5")) {
        baseDir = new java.io.File("C:\\Documents and Settings");
    } else {
        String userHome = System.getProperty("user.home");
        if (userHome == null) {
            throw new IllegalStateException("Unable to determine user home directory (user.home is null)");
        }
        baseDir = new java.io.File(userHome);
    }
    java.io.File configDir = new java.io.File(baseDir, "lf5");
    if (!configDir.exists()) {
        try {
            if (!configDir.mkdirs()) {
                throw new RuntimeException("Failed to create configuration directory: " + configDir.getAbsolutePath());
            }
        } catch (SecurityException se) {
            throw new RuntimeException("Security exception while creating configuration directory: " + se.getMessage(), se);
        }
    }
}

