    if (offset < 0 || offset + 7 >= data.length) {
        throw new IllegalArgumentException("Invalid offset for reading long: " + offset);
    }
    // Read the high 4 bytes
    int high = ((data[offset] & 0xFF) << 24) |
               ((data[offset + 1] & 0xFF) << 16) |
               ((data[offset + 2] & 0xFF) << 8) |
               (data[offset + 3] & 0xFF);
    // Read the low 4 bytes
    int low  = ((data[offset + 4] & 0xFF) << 24) |
               ((data[offset + 5] & 0xFF) << 16) |
               ((data[offset + 6] & 0xFF) << 8) |
               (data[offset + 7] & 0xFF);
    // Combine into a long (big-endian)
    return ((long) high << 32) | (low & 0xffffffffL);
}

