protected List<TimeRange> buildTimeRanges(long start, long end) {
    List<TimeRange> ranges = new ArrayList<>();
    if (start >= end) {
        return ranges; // No valid range to split
    }
    if (FETCH_DATA_DURATION <= 0) {
        // If duration is not positive, fallback to a single range
        ranges.add(new TimeRange(start, end));
        return ranges;
    }

    long current = start;
    while (current < end) {
        long next = current + FETCH_DATA_DURATION;
        // Handle overflow: if addition would wrap around to a negative or overflow beyond end
        if (next < current || next > end) {
            next = end;
        }
        ranges.add(new TimeRange(current, next));
        current = next;
    }
    return ranges;
}

protected List<TimeRange> buildTimeRanges(long start, long end) {
    List<TimeRange> ranges = new ArrayList<>();
    if (start > end || FETCH_DATA_DURATION <= 0) {
        return ranges;
    }
    long current = start;
    while (current < end) {
        long next = Math.min(current + FETCH_DATA_DURATION, end);
        if (next == current) { // prevent infinite loop if FETCH_DATA_DURATION == 0
            break;
        }
        ranges.add(new TimeRange(current, next));
        current = next;
    }
    return ranges;
}

protected java.util.List<TimeRange> buildTimeRanges(long start, long end) {
    java.util.List<TimeRange> ranges = new java.util.ArrayList<>();
    // Validate inputs
    if (start >= end) {
        return ranges;
    }
    if (FETCH_DATA_DURATION <= 0) {
        throw new IllegalArgumentException("FETCH_DATA_DURATION must be a positive value");
    }
    long current = start;
    while (current < end) {
        long remaining = end - current;          // guaranteed positive
        long step = remaining > FETCH_DATA_DURATION ? FETCH_DATA_DURATION : remaining;
        long next = current + step;
        ranges.add(new TimeRange(current, next));
        current = next;
    }
    return ranges;
}

protected List<TimeRange> buildTimeRanges(long start, long end) {
    List<TimeRange> ranges = new ArrayList<>();
    // Validate input
    if (start >= end) {
        return ranges; // return empty list if range is invalid or zero-length
    }
    if (FETCH_DATA_DURATION <= 0) {
        throw new IllegalArgumentException("FETCH_DATA_DURATION must be positive");
    }

    long curStart = start;
    while (curStart < end) {
        // Prevent overflow when adding duration
        long curEnd;
        if (curStart > Long.MAX_VALUE - FETCH_DATA_DURATION) {
            curEnd = end;
        } else {
            long maybeEnd = curStart + FETCH_DATA_DURATION;
            curEnd = maybeEnd < end ? maybeEnd : end;
        }
        if (curStart >= curEnd) {
            // Just in case to avoid zero-length ranges
            break;
        }
        ranges.add(new TimeRange(curStart, curEnd));
        curStart = curEnd;
    }
    return ranges;
}

protected List<TimeRange> buildTimeRanges(long start, long end){
    List<TimeRange> ranges = new ArrayList<>();
    if (start >= end) {
        return ranges; // no range needed
    }
    if (FETCH_DATA_DURATION <= 0) {
        // Avoid infinite loop, return the whole range as one
        ranges.add(new TimeRange(start, end));
        return ranges;
    }
    long current = start;
    while (current < end) {
        long remaining = end - current;
        long nextEnd;
        if (remaining <= FETCH_DATA_DURATION) {
            nextEnd = end;
        } else {
            // Prevent overflow when adding FETCH_DATA_DURATION
            if (FETCH_DATA_DURATION > Long.MAX_VALUE - current) {
                nextEnd = end;
            } else {
                nextEnd = current + FETCH_DATA_DURATION;
            }
        }
        ranges.add(new TimeRange(current, nextEnd));
        current = nextEnd;
    }
    return ranges;
}

