static long compressTimeBucket(long timeBucket, int dayStep) {
    // Validate dayStep
    if (dayStep <= 0) {
        throw new IllegalArgumentException("dayStep must be a positive integer");
    }
    if (timeBucket <= 0) {
        throw new IllegalArgumentException("timeBucket must be a positive long representing YYYYMMDD");
    }

    // Convert long to String, ensuring it has at least 8 digits
    String s = Long.toString(timeBucket);
    if (s.length() < 8) {
        // Pad with leading zeros if necessary
        s = String.format("%08d", timeBucket);
    }
    if (s.length() != 8) {
        throw new IllegalArgumentException("timeBucket must be in YYYYMMDD format");
    }

    try {
        java.time.LocalDate date = java.time.LocalDate.parse(s, java.time.format.DateTimeFormatter.BASIC_ISO_DATE);
        int day = date.getDayOfMonth();
        int bucketDay = 1 + ((day - 1) / dayStep) * dayStep;

        java.time.LocalDate bucketDate = java.time.LocalDate.of(date.getYear(), date.getMonth(), bucketDay);
        long result = bucketDate.getYear() * 10000L + bucketDate.getMonthValue() * 100L + bucketDate.getDayOfMonth();
        return result;
    } catch (java.time.format.DateTimeParseException | java.time.DateTimeException e) {
        throw new IllegalArgumentException("Invalid timeBucket format or date: " + timeBucket, e);
    }
}

static long compressTimeBucket(long timeBucket,int dayStep){
