    }

    String timeStr = Long.toString(timeBucket);
    if (timeStr.length() != 8) {
        throw new IllegalArgumentException("timeBucket must be in yyyyMMdd format");
    }

    try {
        int year = Integer.parseInt(timeStr.substring(0, 4));
        int month = Integer.parseInt(timeStr.substring(4, 6));
        int day = Integer.parseInt(timeStr.substring(6, 8));

        // Compute the compressed day
        int newDay = ((day - 1) / dayStep) * dayStep + 1;

        // Ensure day is two digits
        String newDayStr = String.format("%02d", newDay);
        String newDateStr = String.format("%04d%02d%s", year, month, newDayStr);

        return Long.parseLong(newDateStr);
    } catch (NumberFormatException e) {
        throw new IllegalArgumentException("timeBucket contains invalid numeric values", e);
    } catch (Exception e) {
        throw new RuntimeException("Unexpected error while compressing time bucket", e);
    }
}

static long compressTimeBucket(long timeBucket, int dayStep) {
    if (dayStep <= 0) {
        throw new IllegalArgumentException("dayStep must be positive");
    }

    long year = timeBucket / 10000;
    long month = (timeBucket / 100) % 100;
    long day = timeBucket % 100;

    // Basic validation of month
    if (month < 1 || month > 12) {
        return timeBucket;
    }

    // Validate day using YearMonth to get days in month
    int maxDay;
    try {
        java.time.YearMonth ym = java.time.YearMonth.of((int) year, (int) month);
        maxDay = ym.lengthOfMonth();
    } catch (java.time.DateTimeException e) {
        return timeBucket;
    }

    if (day < 1 || day > maxDay) {
        return timeBucket;
    }

    int compressedDay = 1 + (int) ((day - 1) / dayStep) * dayStep;
    if (compressedDay > maxDay) {
        compressedDay = maxDay;
    }

    return year * 10000 + month * 100 + compressedDay;
}

