public static int computeUTF8Size(final CharSequence str, final int index, final int len){
    if (str == null) {
        throw new NullPointerException("str is null");
    }
    if (index < 0 || len < 0 || index > str.length() - len) {
        throw new IndexOutOfBoundsException("index: " + index + " len: " + len);
    }
    int size = 0;
    int end = index + len;
    int i = index;
    while (i < end) {
        char ch = str.charAt(i);
        if (ch < 0x80) {
            size += 1;
        } else if (ch < 0x800) {
            size += 2;
        } else {
            // Handle surrogate pairs
            if (Character.isHighSurrogate(ch) && i + 1 < end
                    && Character.isLowSurrogate(str.charAt(i + 1))) {
                size += 4;
                i++; // skip low surrogate
            } else {
                size += 3;
            }
        }
        i++;
    }
    return size;
}

public static int computeUTF8Size(final CharSequence str, final int index, final int len) {
    if (str == null) {
        throw new NullPointerException("Input string cannot be null");
    }
    if (index < 0 || len < 0) {
        throw new IllegalArgumentException("Index and length must be non‑negative");
    }
    if (index + len > str.length()) {
        throw new IllegalArgumentException("Index + length exceeds string length");
    }
    int end = index + len;
    int size = 0;
    int i = index;
    while (i < end) {
        char ch = str.charAt(i);
        if (ch < 0x80) {
            size += 1;                 // One byte
        } else if (ch < 0x800) {
            size += 2;                 // Two bytes
        } else if (ch >= 0xD800 && ch <= 0xDBFF) { // High surrogate
            if (i + 1 < end) {
                char low = str.charAt(i + 1);
                if (low >= 0xDC00 && low <= 0xDFFF) {
                    // Valid surrogate pair -> code point > 0xFFFF
                    size += 4;         // Four bytes
                    i++;               // Skip low surrogate
                } else {
                    // Unpaired high surrogate treated as replacement character
                    size += 3;
                }
            } else {
                // Unpaired high surrogate at end
                size += 3;
            }
        } else if (ch >= 0xDC00 && ch <= 0xDFFF) {
            // Unpaired low surrogate
            size += 3;
        } else {
            size += 3; // Surrogateless BMP character
        }
        i++;
    }
    return size;
}

