    }
    final int end = index + len;
    if (end > str.length()) {
        throw new IllegalArgumentException("Specified range exceeds string length");
    }

    int utf8Size = 0;
    for (int i = index; i < end; i++) {
        int ch = str.charAt(i);
        if (ch <= 0x7F) {
            utf8Size += 1;
        } else if (ch <= 0x7FF) {
            utf8Size += 2;
        } else if (Character.isHighSurrogate((char) ch)) {
            // Check for a following low surrogate
            if (i + 1 < end) {
                char low = str.charAt(i + 1);
                if (Character.isLowSurrogate(low)) {
                    // Valid surrogate pair -> 4 bytes
                    utf8Size += 4;
                    i++; // skip low surrogate
                    continue;
                }
            }
            // Unpaired high surrogate treated as replacement character (3 bytes)
            utf8Size += 3;
        } else {
            // Regular BMP character that is not ASCII and not surrogate
            utf8Size += 3;
        }
    }
    return utf8Size;
}

public static int computeUTF8Size(final CharSequence str, final int index, final int len) {
    if (str == null) {
        throw new NullPointerException("Input CharSequence is null");
    }
    if (index < 0 || len < 0) {
        throw new IllegalArgumentException("index and len must be non‑negative");
    }
    final int strLen = str.length();
    if (index > strLen - len) {
        throw new IllegalArgumentException("index + len exceeds input length");
    }
    int end = index + len;
    int i = index;
    int size = 0;
    while (i < end) {
        char ch = str.charAt(i);
        int cp;
        // Handle surrogate pairs
        if (Character.isHighSurrogate(ch)) {
            if (i + 1 < end) {
                char low = str.charAt(i + 1);
                if (Character.isLowSurrogate(low)) {
                    cp = Character.toCodePoint(ch, low);
                    i += 2;
                    // UTF‑8 for supplementary code points always 4 bytes
                    size += 4;
                    continue;
                }
            }
        }
        // single char (or unpaired surrogate)
        cp = ch;
        i += 1;
        if (cp <= 0x7F) {
            size += 1;
        } else if (cp <= 0x7FF) {
            size += 2;
        } else if (cp <= 0xFFFF) {
            size += 3;
        } else {
            // Theoretically unreachable for single char
            size += 4;
        }
    }
    return size;
}

public static int computeUTF8Size(final CharSequence str, final int index, final int len) {
    if (str == null) {
        throw new NullPointerException("Input CharSequence is null");
    }
    if (index < 0 || len < 0) {
        throw new IndexOutOfBoundsException("index and length must be non‑negative");
    }
    int end = index + len;
    if (end > str.length()) {
        throw new IndexOutOfBoundsException("index + length exceeds the length of the sequence");
    }

    int bytes = 0;
    for (int i = index; i < end; ) {
        char ch = str.charAt(i);
        int codePoint;

        if (Character.isHighSurrogate(ch)) {
            if (i + 1 < end) {
                char low = str.charAt(i + 1);
                if (Character.isLowSurrogate(low)) {
                    codePoint = Character.toCodePoint(ch, low);
                    i += 2;
                } else {
                    // Invalid surrogate pair: treat as replacement character
                    codePoint = 0xFFFD;
                    i += 1;
                }
            } else {
                // High surrogate at the end: invalid, replacement
                codePoint = 0xFFFD;
                i += 1;
            }
        } else if (Character.isLowSurrogate(ch)) {
            // Unmatched low surrogate
            codePoint = 0xFFFD;
            i += 1;
        } else {
            codePoint = ch;
            i += 1;
        }

        if (codePoint <= 0x7F) {
            bytes += 1;
        } else if (codePoint <= 0x7FF) {
            bytes += 2;
        } else if (codePoint <= 0xFFFF) {
            bytes += 3;
        } else {
            bytes += 4;
        }
    }

    return bytes;
}

