    Integer idxObj = map.get(val);
    if (idxObj == null) {
        // Value not present in the set
        return false;
    }
    int idx = idxObj;
    int lastIndex = list.size() - 1;
    int lastVal = list.get(lastIndex);

    // If the element to remove is not the last one, swap it with the last element
    if (idx != lastIndex) {
        list.set(idx, lastVal);
        map.put(lastVal, idx);
    }

    // Remove the last element (which is now the element to delete)
    list.remove(lastIndex);
    map.remove(val);
    return true;
}

