             * first two declared fields (typically representing vertices).
             */
            try {
                java.lang.reflect.Field f1 = edge.getClass().getDeclaredField("u");
                f1.setAccessible(true);
                @SuppressWarnings("unchecked")
                V source = (V) f1.get(edge);
                if (source != null) {
                    vertices.add(source);
                }
                java.lang.reflect.Field f2 = edge.getClass().getDeclaredField("v");
                f2.setAccessible(true);
                @SuppressWarnings("unchecked")
                V target = (V) f2.get(edge);
                if (target != null) {
                    vertices.add(target);
                }
            } catch (Exception ignored) {
                // If we can't access the vertices, skip this edge
            }
        }
    }
    return vertices;
}

