    // If after clamping start is still greater than end, swap to avoid exception
    if (start > end) {
        int temp = start;
        start = end;
        end = temp;
    }

    // Final safety checks (in case of values changed by swap)
    if (start < 0) {
        start = 0;
    }
    if (end > len) {
        end = len;
