public ByteVector putByteArray(final byte[] byteArrayValue, final int byteOffset, final int byteLength) {
    // Validate byteLength
    if (byteLength < 0) {
        throw new IllegalArgumentException("byteLength must not be negative");
    }
    // No bytes to copy
    if (byteLength == 0) {
        return this;
    }

    // Ensure the internal buffer exists
    if (this.array == null) {
        // initial capacity of 32 or larger than required
        int initCap = Math.max(32, byteLength);
        this.array = new byte[initCap];
