    }
}

public static String findAndSubst(String key, Properties props) {
    if (key == null || props == null) {
        return null;
    }
    String value = props.getProperty(key);
    if (value == null) {
        return null;
    }

    // Perform variable substitution of the form ${varName}
    // with a maximum of 10 iterations to avoid infinite recursion.
    int maxIterations = 10;
    int iteration = 0;
    while (iteration < maxIterations) {
        int start = value.indexOf("${");
        if (start == -1) {
            break; // no more placeholders
        }
        int end = value.indexOf('}', start + 2);
        if (end == -1) {
            break; // malformed placeholder
        }
        String varName = value.substring(start + 2, end);
        String varVal = props.getProperty(varName);
        if (varVal == null) {
            varVal = ""; // treat missing property as empty string
        }
        value = value.substring(0, start) + varVal + value.substring(end + 1);
        iteration++;
    }

    return value;
}

