private static String findAndSubstInternal(String key, java.util.Properties props, java.util.Set<String> visited) {
    if (visited.contains(key)) {
        // Circular reference detected; return null to avoid infinite recursion
        return null;
    }
    visited.add(key);

    String value = props.getProperty(key);
    if (value == null) {
        return null;
    }

    java.util.regex.Pattern pattern = java.util.regex.Pattern.compile("\\$\\{([^}]+)}");
    java.util.regex.Matcher matcher = pattern.matcher(value);
    java.lang.StringBuffer result = new java.lang.StringBuffer();

    while (matcher.find()) {
        String varName = matcher.group(1);
        String replacement = findAndSubstInternal(varName, props, visited);
        if (replacement == null) {
            replacement = "";
        }
        matcher.appendReplacement(result, java.util.regex.Matcher.quoteReplacement(replacement));
    }
    matcher.appendTail(result);

    visited.remove(key);
    return result.toString();
}

