    if (value == null) {
        return null;
    }
    // Perform simple ${var} substitution using the same properties map.
    // Limit number of iterations to avoid infinite recursion.
    final int maxIterations = 10;
    String result = value;
    for (int i = 0; i < maxIterations; i++) {
        int start = result.indexOf("${");
        if (start == -1) {
            break;
        }
        int end = result.indexOf('}', start + 2);
        if (end == -1) {
            break;
        }
        String varName = result.substring(start + 2, end);
        String replacement = props.getProperty(varName);
        if (replacement == null) {
            // If the variable is not defined, leave it unchanged to avoid infinite loops.
            start = end + 1;
