    // regionMatches(startInThis, offsetInOther, other, startInOther, length)
    // The Java signature: regionMatches(boolean ignoreCase, int thisStart, String other, int otherStart, int length)
    return str.regionMatches(ignoreCase, strLen - suffixLen, suffix, 0, suffixLen);
