    }

    // Get the raw path (percent encoded) to preserve the original representation
    String rawPath = u.getRawPath();

    // If the path is null or empty, return an empty list
    if (rawPath == null || rawPath.isEmpty()) {
        return new java.util.ArrayList<>();
    }

    // For an absolute path, ignore the leading '/'
    int startIndex = rawPath.startsWith("/") ? 1 : 0;
    String pathToParse = rawPath.substring(startIndex);

    // If there's nothing after the optional leading slash (e.g., path "/"), return an empty list
    if (pathToParse.isEmpty()) {
        return new java.util.ArrayList<>();
    }

    // Split on '/' to get raw path segments. The negative limit ensures trailing empty segments are retained.
    String[] rawSegments = pathToParse.split("/", -1);
    java.util.List<PathSegmentImpl> result = new java.util.ArrayList<>(rawSegments.length);

    for (String rawSegment : rawSegments) {
        String segment = rawSegment;
        if (decode && !segment.isEmpty()) {
            try {
                segment = java.net.URLDecoder.decode(segment, java.nio.charset.StandardCharsets.UTF_8.name());
            } catch (java.io.UnsupportedEncodingException e) {
                // UTF-8 is guaranteed to be supported; rethrow as a runtime exception if it ever fails
                throw new RuntimeException("UTF-8 decoding not supported", e);
            }
        }
        // Create a PathSegmentImpl instance with the (possibly decoded) segment
        result.add(new PathSegmentImpl(segment));
    }

    return result;
}

