    try {
        if (descriptor.startsWith("(")) {
            // Method descriptor: pop argument types only.
            if (!descriptor.endsWith(")")) {
                throw new IllegalArgumentException("Malformed method descriptor: " + descriptor);
            }

            int pos = 1; // skip '('
            while (descriptor.charAt(pos) != ')') {
                int slots = 1;
                char c = descriptor.charAt(pos);

                if (c == '[') {
                    // Array type – consume all '[' characters.
                    while (descriptor.charAt(pos) == '[') {
                        pos++;
                    }
                    // Element type
                    if (descriptor.charAt(pos) == 'L') {
                        int semicolon = descriptor.indexOf(';', pos);
                        if (semicolon < 0) {
                            throw new IllegalArgumentException("Invalid object type in descriptor: " + descriptor);
                        }
                        pos = semicolon + 1; // skip past ';'
                    } else {
                        pos++; // single primitive type
                    }
                } else if (c == 'L') {
                    // Object type
                    int semicolon = descriptor.indexOf(';', pos);
                    if (semicolon < 0) {
                        throw new IllegalArgumentException("Invalid object type in descriptor: " + descriptor);
                    }
                    pos = semicolon + 1;
                } else {
                    // Primitive type
                    if (c == 'J' || c == 'D') {
                        slots = 2;
                    }
                    pos++;
                }

                slotsToPop += slots;
            }
        } else {
            // Type descriptor (single value)
            int pos = 0;
            char c = descriptor.charAt(pos);
            int slots = 1;

            if (c == '[') {
                // Array type
                while (descriptor.charAt(pos) == '[') {
                    pos++;
