private void pop(final String descriptor) {
    if (descriptor == null || descriptor.isEmpty()) {
        return;
    }

    // Helper to determine how many stack slots a type descriptor consumes.
    java.util.function.IntFunction<Integer> slotsFor = desc -> {
        char first = desc.charAt(0);
        return (first == 'J' || first == 'D') ? 2 : 1;
    };

    // Parse the argument types from a descriptor string.
    java.util.List<String> types = new java.util.ArrayList<>();
    int i = 0;
    try {
        if (descriptor.charAt(0) == '(') { // method descriptor
            i = 1; // skip '('
            while (descriptor.charAt(i) != ')') {
                int start = i;
                char c = descriptor.charAt(i);
                if (c == '[') {
                    // array type: consume all '['
                    while (descriptor.charAt(i) == '[') {
                        i++;
                    }
                    // element type can be object or primitive
                    char elem = descriptor.charAt(i);
                    if (elem == 'L') {
                        while (descriptor.charAt(i) != ';') {
                            i++;
                        }
                    }
                } else if (c == 'L') {
                    // object type
                    while (descriptor.charAt(i) != ';') {
                        i++;
                    }
                }
                // include the full type descriptor
                types.add(descriptor.substring(start, i + 1));
                i++; // move to next character after current type
            }

            // Skip the return type after ')'
            int start = i + 1;
            char c = descriptor.charAt(start);
            if (c == '[') {
                while (descriptor.charAt(start) == '[') {
                    start++;
                }
                if (descriptor.charAt(start) == 'L') {
                    while (descriptor.charAt(start) != ';') {
                        start++;
                    }
                }
            } else if (c == 'L') {
                while (descriptor.charAt(start) != ';') {
                    start++;
                }
            }
            // No further action needed for return type
        } else { // field descriptor
            types.add(descriptor);
        }
    } catch (IndexOutOfBoundsException e) {
        throw new IllegalArgumentException("Invalid descriptor: " + descriptor, e);
    }

    // Pop the stack in reverse order of the argument list
    for (int idx = types.size() - 1; idx >= 0; idx--) {
        String type = types.get(idx);
        int slots = slotsFor.apply(type);
        if (type.charAt(0) == 'V') {
            slots = 0; // void, nothing to pop
        }
        for (int s = 0; s < slots; s++) {
            if (outputFrameStack == null || outputFrameStack.isEmpty()) {
                throw new IllegalStateException("Stack underflow while popping type: " + type);
            }
            outputFrameStack.removeLast();
        }
    }
}

