        int count = 0;
        for (String part : parts) {
            if (!part.isEmpty()) {
                count++;
            }
        }
        File[] files = new File[count];
        int idx = 0;
        for (String part : parts) {
            if (!part.isEmpty()) {
                files[idx++] = new File(part);
