private void enlarge(final int size) {
    if (size <= 0) {
        throw new IllegalArgumentException("size must be positive");
    }
    int currentCapacity = (buffer != null) ? buffer.length : 0;
    int newCapacity;
    if (currentCapacity == 0) {
        newCapacity = Math.max(16, size);
    } else {
        long required = (long) this.size + size;
        long doubled = (long) currentCapacity * 2;
        long cap = Math.max(doubled, required);
        if (cap > Integer.MAX_VALUE) {
            throw new OutOfMemoryError("Required capacity exceeds maximum array size");
        }
        newCapacity = (int) cap;
    }
    byte[] newBuffer = new byte[newCapacity];
    if (buffer != null) {
        System.arraycopy(buffer, 0, newBuffer, 0, this.size);
    }
    buffer = newBuffer;
}

private void enlarge(final int size){
    // The size must be non‑negative.
    if (size < 0) {
        throw new IllegalArgumentException("size must be non‑negative");
    }
    // If no internal buffer yet, create one of a reasonable initial size.
    if (this.data == null) {
        int newCap = Math.max(8, size);
        if (newCap > this.max) {
            newCap = this.max;
        }
        this.data = new byte[newCap];
        return;
    }
    // Compute the new number of bytes that will be occupied.
    final int needed = this.count + size;
    if (needed > this.data.length) {
        // Check against the maximum allowed size.
        if (needed > this.max) {
            throw new ArrayIndexOutOfBoundsException(
                "ByteVector exceeds maximum size " + this.max);
        }
        // Grow the buffer: try to double its size, but guarantee we can hold 'needed'.
        int newCap = Math.max(this.data.length << 1, needed);
        if (newCap > this.max) {
            newCap = this.max;
        }
        byte[] newData = new byte[newCap];
        if (this.count > 0) {
            System.arraycopy(this.data, 0, newData, 0, this.count);
        }
        this.data = newData;
    }
}

