    }
    // Use a long to avoid integer overflow when adding size
    long newLenLong = (long) this.size + size;
    // Prevent excessively large arrays (leakage or mis‑specified size)
    if (newLenLong > Integer.MAX_VALUE - 4) {
        throw new RuntimeException("ByteVector too large");
    }
    int newLen = (int) newLenLong;
    try {
        byte[] newArray = new byte[newLen];
        System.arraycopy(this.array, 0, newArray, 0, this.size);
        this.array = newArray;
