    if (size < 0) {
        throw new IllegalArgumentException("size must be non‑negative");
    }
    // Compute the capacity that is needed to accommodate the new data
    int newCap = this.pos + size;   // 'pos' is the current number of bytes stored
    // If the current capacity is insufficient, grow the buffer
    if (newCap > this.cap) {       // 'cap' is the current buffer length
        // Double the capacity, but make sure it is at least big enough for the new data
        int newCapacity = this.cap << 1;
        if (newCapacity < newCap || newCapacity < 0) { // handle overflow and tiny buffers
            newCapacity = newCap;
        }
        // Allocate a new buffer and copy the existing data
        byte[] newBuffer = new byte[newCapacity];
        System.arraycopy(this.buffer, 0, newBuffer, 0, this.pos);
        // Replace the old buffer and update the stored capacity
        this.buffer = newBuffer;
        this.cap = newCapacity;
    }
