public static String capitalize(String name) {
    if (name == null) {
        return null;
    }
    int len = name.length();
    if (len == 0) {
        return name;
    }
    // If the second character is uppercase, keep the string unchanged
    if (len > 1 && Character.isUpperCase(name.charAt(1))) {
        return name;
    }
    // Otherwise, capitalize the first character
    char first = name.charAt(0);
    char upperFirst = Character.toUpperCase(first);
    if (first == upperFirst) {
        return name;
    }
    if (len == 1) {
        return String.valueOf(upperFirst);
    }
    return upperFirst + name.substring(1);
}

public static String capitalize(String name) {
    if (name == null || name.isEmpty()) {
        return name;
    }
    // If the first two characters are uppercase, we keep the string unchanged
    // to mirror the reverse of Introspector.decapitalize behavior.
    if (name.length() > 1) {
        char first = name.charAt(0);
        char second = name.charAt(1);
        if (Character.isUpperCase(first) && Character.isUpperCase(second)) {
            return name;
        }
    }
    // Capitalize the first character
    if (name.length() == 1) {
        return Character.toString(Character.toUpperCase(name.charAt(0)));
    }
    return Character.toString(Character.toUpperCase(name.charAt(0))) + name.substring(1);
}

