public String format(final LoggingEvent event){
    if (event == null) {
        return "";
    }
    try {
        // Build the basic log line
        StringBuilder sb = new StringBuilder();

        // Timestamp in ISO‑8601
        long ts = event.getTimeStamp();
        sb.append(java.time.Instant.ofEpochMilli(ts).toString());
        sb.append(' ');

        // Thread name
        String thread = event.getThreadName();
        sb.append('[').append(thread != null ? thread : "unknown").append(']');
        sb.append(' ');

        // Log level
        sb.append(event.getLevel());
        sb.append(" - ");

        // Logger name
        sb.append(event.getLoggerName());
        sb.append(" - ");

        // Log message
        String message = event.getRenderedMessage();
        if (message == null) {
            Object msgObj = event.getMessage();
            message = msgObj == null ? "" : msgObj.toString();
        }
        sb.append(message);

        // Append throwable information if present
        org.apache.log4j.spi.ThrowableInformation ti = event.getThrowableInformation();
        if (ti != null) {
            Throwable t = ti.getThrowable();
            if (t != null) {
                sb.append(System.lineSeparator());
                java.io.StringWriter sw = new java.io.StringWriter();
                t.printStackTrace(new java.io.PrintWriter(sw));
                sb.append(sw.toString());
            }
        }

        return sb.toString();
    } catch (Throwable e) {
        // Fallback: return the rendered message or empty string on failure
        String fallback = (event.getRenderedMessage() != null) ? event.getRenderedMessage()
                : ((event.getMessage() != null) ? event.getMessage().toString() : "");
        return fallback;
    }
}

