                            "Invalid constant pool index for ITEM_OBJECT at index " + i);
                }
                stackMapTableEntries.add((byte) (cpoolIndex >> 8));
                stackMapTableEntries.add((byte) (cpoolIndex & 0xFF));
                break;
            }
            case VerificationInfo.ITEM_UNINITIALIZED: {   // tag = 8
                final int offset = info.getOffset();
                if (offset < 0) {
