        if (num < 0 || num > Character.MAX_VALUE) {
            throw new IllegalArgumentException("Numeric value out of char range: " + num);
        }
        return (char) num;
    }

    throw new IllegalArgumentException(
        "Cannot convert value of type " + value.getClass().getName() + " to java.lang.Character");
}

@Override
protected Object convertToType(final Class<?> type, final Object value) throws Exception {
    // Ensure the requested conversion is for Character/char only
    if (type != Character.class && type != char.class) {
        throw new IllegalArgumentException("Unsupported target type: " + type.getName());
    }

    // Null values result in null (or the default char value if primitive is demanded)
    if (value == null) {
        // For primitive char target, null cannot be represented; return '\0'
        if (type == char.class) {
            return Character.valueOf('\u0000');
        }
        return null;
    }

    // Direct Character instance
    if (value instanceof Character) {
        return (Character) value;
    }

    // Numeric conversion: number -> char via int value
    if (value instanceof Number) {
        int intVal = ((Number) value).intValue();
        // char range is 0 to 65535
        if (intVal < Character.MIN_VALUE || intVal > Character.MAX_VALUE) {
            throw new Exception("Numeric value " + intVal + " out of char range");
        }
        return Character.valueOf((char) intVal);
    }

    // Char sequence: String, StringBuilder, etc. Requires length 1
    if (value instanceof CharSequence) {
        CharSequence seq = (CharSequence) value;
        if (seq.length() == 1) {
            return Character.valueOf(seq.charAt(0));
        }
        throw new Exception("String of length " + seq.length() + " cannot be converted to a single character");
    }

    // Boolean conversion: custom mapping (true -> 't', false -> 'f')
    if (value instanceof Boolean) {
        return Character.valueOf((Boolean) value ? 't' : 'f');
    }

    // Fallback: use toString(); must be length 1
    String str = value.toString();
    if (str.length() == 1) {
        return Character.valueOf(str.charAt(0));
    }

    throw new Exception("Cannot convert value [" + value + "] of type [" + value.getClass().getName() + "] to a character");
}

@Override
protected Object convertToType(final Class<?> type, final Object value) throws Exception {
    // Only support conversion to java.lang.Character or primitive char
    if (type == null) {
        throw new IllegalArgumentException("Target type must not be null");
    }
    if (type != Character.class && type != char.class) {
        throw new IllegalArgumentException("Unsupported target type: " + type.getName());
    }

    if (value == null) {
        return null;
    }

    try {
        if (value instanceof Character) {
            return value; // already a Character
        }

        if (value instanceof Number) {
            // Convert numeric values to corresponding char
            int intValue = ((Number) value).intValue();
            return (char) intValue;
        }

        if (value instanceof CharSequence) {
            CharSequence cs = (CharSequence) value;
            if (cs.length() == 1) {
                return cs.charAt(0);
            }
            // Try parsing as numeric string
            String str = cs.toString().trim();
            if (!str.isEmpty()) {
                try {
                    int parsed = Integer.parseInt(str);
                    return (char) parsed;
                } catch (NumberFormatException ignored) {
                }
            }
        }

        if (value instanceof String) {
            String str = (String) value;
            if (str.length() == 1) {
                return str.charAt(0);
            }
            // Try numeric representation
            try {
                int parsed = Integer.parseInt(str.trim());
                return (char) parsed;
            } catch (NumberFormatException ignored) {
            }
        }

        // Fallback: try toString and use first character if possible
        String str = value.toString();
        if (str != null && str.length() == 1) {
            return str.charAt(0);
        }

    } catch (Exception e) {
        // Wrap any unexpected exception in a generic Exception with a clear message
        throw new Exception("Failed to convert value [" + value + "] to java.lang.Character: " + e.getMessage(), e);
    }

    throw new Exception("Cannot convert value [" + value + "] to java.lang.Character");
}

@Override
