    // Only support conversion when the target type is Character or char
    if (type == null || (!Character.class.equals(type) && !char.class.equals(type))) {
        throw new IllegalArgumentException("Target type must be java.lang.Character or char");
    }

    // Null values are converted to null
    if (value == null) {
        return null;
    }

    // If already a Character instance, return it directly
    if (value instanceof Character) {
        return value;
    }

    // If the value is a CharSequence (String, StringBuilder, etc.)
    if (value instanceof CharSequence) {
        CharSequence cs = (CharSequence) value;
        if (cs.length() == 1) {
            return cs.charAt(0);
        } else {
            throw new IllegalArgumentException(
                    "Cannot convert CharSequence to Character because length is not 1: \"" + cs + "\"");
        }
    }

    // If the value is a Number, cast its integer value to a char
    if (value instanceof Number) {
        return (char) ((Number) value).intValue();
    }

    // Attempt to convert via the string representation
    String str = value.toString();
    if (str.length() == 1) {
        return str.charAt(0);
    }

    // If none of the above work, throw an exception
    throw new IllegalArgumentException(
            "Cannot convert value of type " + value.getClass().getName()
            + " to java.lang.Character: cannot determine a single character");
