public static String trimTrailingWhitespace(String str) {
    // Handle null input
    if (str == null) {
        return null;
    }
    int len = str.length();
    int i = len - 1;
    // Move backwards while there is whitespace at the end of the string
    while (i >= 0 && Character.isWhitespace(str.charAt(i))) {
        i--;
    }
    // If no trailing whitespace, return the original string
    if (i == len - 1) {
        return str;
    }
    // If the entire string was whitespace, return an empty string
    if (i < 0) {
        return "";
