private static Object convertJsonValue(javax.json.JsonValue val) {
    JsonValue.ValueType type = val.getValueType();
    switch (type) {
        case OBJECT:
            javax.json.JsonObject obj = val.asJsonObject();
            Map<String, Object> map = new HashMap<>();
            obj.forEach((k, v) -> map.put(k, convertJsonValue(v)));
            return map;
        case ARRAY:
            javax.json.JsonArray arr = val.asJsonArray();
            List<Object> list = new ArrayList<>();
            for (JsonValue item : arr) {
                list.add(convertJsonValue(item));
            }
            return list;
        case STRING:
            return ((javax.json.JsonString) val).getString();
        case NUMBER:
            javax.json.JsonNumber num = (javax.json.JsonNumber) val;
            return num.isIntegral() ? num.longValue() : num.doubleValue();
        case TRUE:
            return Boolean.TRUE;
        case FALSE:
            return Boolean.FALSE;
        case NULL:
            return null;
        default:
            return null;
    }
}

