                        list.add(buildListFromJsonArray(el.getAsJsonArray()));
                    } else if (el.isJsonPrimitive()) {
                        list.add(convertJsonPrimitive(el.getAsJsonPrimitive()));
                    } else if (el.isJsonNull()) {
