/** Helper to recursively convert a JsonArray to a List<Object> */
private List<Object> buildListFromJsonArray(JsonArray jsonArray) {
    List<Object> result = new ArrayList<>();
    for (JsonElement el : jsonArray) {
        if (el.isJsonObject()) {
            result.add(buildContent(el.getAsJsonObject()));
        } else if (el.isJsonArray()) {
            result.add(buildListFromJsonArray(el.getAsJsonArray()));
        } else if (el.isJsonPrimitive()) {
            result.add(convertJsonPrimitive(el.getAsJsonPrimitive()));
        } else if (el.isJsonNull()) {
            result.add(null);
        }
    }
    return result;
}

/** Convert a JsonPrimitive to the corresponding Java object */
private Object convertJsonPrimitive(JsonPrimitive prim) {
    if (prim.isBoolean()) {
        return prim.getAsBoolean();
    } else if (prim.isNumber()) {
        return prim.getAsNumber();
    } else if (prim.isString()) {
        return prim.getAsString();
    }
    return prim.getAsString(); // fallback
}

