protected int removeUnusedNodes() {
    try {
        int removedCount = 0;
        // Assume the root node of the category tree is stored in a field named 'root'
        Category rootNode = this.root;
        if (rootNode == null) {
            return 0;
        }

        // If the root itself is inactive, remove the entire tree and return the count
        if (!rootNode.isActive()) {
            // Count all nodes in the subtree rooted at rootNode
            Deque<Category> countStack = new java.util.ArrayDeque<>();
            countStack.push(rootNode);
            while (!countStack.isEmpty()) {
                Category cur = countStack.pop();
                removedCount++;
                java.util.List<Category> children = cur.getChildren();
                if (children != null) {
                    countStack.addAll(children);
                }
            }
            this.root = null;
            return removedCount;
        }

        // Use a stack for depth‑first traversal to process children
        Deque<Category> stack = new java.util.ArrayDeque<>();
        stack.push(rootNode);

        while (!stack.isEmpty()) {
            Category current = stack.pop();
            java.util.List<Category> children = current.getChildren();
            if (children == null || children.isEmpty()) {
                continue;
            }

            java.util.Iterator<Category> it = children.iterator();
            while (it.hasNext()) {
                Category child = it.next();
                if (!child.isActive()) {
                    // Count nodes in the inactive subtree
                    int subtreeCount = 0;
                    Deque<Category> tempStack = new java.util.ArrayDeque<>();
                    tempStack.push(child);
                    while (!tempStack.isEmpty()) {
                        Category t = tempStack.pop();
                        subtreeCount++;
                        java.util.List<Category> tChildren = t.getChildren();
                        if (tChildren != null) {
                            tempStack.addAll(tChildren);
                        }
                    }
                    removedCount += subtreeCount;
                    it.remove(); // Remove inactive child from parent’s list
                } else {
                    stack.push(child); // Active child will be processed later
                }
            }
        }

        return removedCount;
    } catch (Exception e) {
        throw new RuntimeException("Failed to remove unused nodes", e);
    }
}

