        for (Iterator<Category> it = new java.util.ArrayList<>(children).iterator(); it.hasNext();) {
            Category child = it.next();
            removed += pruneNode(child, node);
        }
    }

    // If the current node is inactive, remove it from its parent
    if (!node.isActive()) {
        if (parent != null) {
            parent.removeChild(node);
        } else {
            // The root itself is inactive; clear the entire tree
            root = null;
        }
        removed++; // Count this node as removed
    }

    return removed;
}

