private int removeFrom(Category node) {
    int count = 0;
    if (node == null) {
        return count;
    }
    try {
        java.util.List<Category> children = node.getChildren();
        if (children == null) {
            return count;
        }
        java.util.Iterator<Category> it = children.iterator();
        while (it.hasNext()) {
            Category child = it.next();
            if (child == null) {
                continue;
            }
            try {
                if (!child.isActive()) {
                    it.remove();          // removes the child from parent's list
                    count++;              // count the removed node
                } else {
                    count += removeFrom(child); // recurse into active subtree
                }
            } catch (Exception inner) {
                // If an individual child causes trouble, skip it
                continue;
            }
        }
    } catch (Exception outer) {
        // Ignore if retrieving or iterating children fails
    }
    return count;
}

protected int removeUnusedNodes(){
    int removed = 0;
    try {
        // Assume the category tree root is stored in a field named `root`
        if (root == null) {
            return 0;
        }
        // If the root itself is inactive, remove the entire tree
        if (!root.active) {
            // Count all nodes in the subtree rooted at `root`
            Stack<CategoryNode> stackForCount = new Stack<>();
            stackForCount.push(root);
            while (!stackForCount.isEmpty()) {
                CategoryNode curr = stackForCount.pop();
                removed++;
                for (CategoryNode child : curr.children) {
                    stackForCount.push(child);
                }
            }
            // Invalidate the root reference
            root = null;
            return removed;
        }

        // Traverse the tree breadth-first (using a stack for DFS)
        Stack<CategoryNode> traversalStack = new Stack<>();
        traversalStack.push(root);

        while (!traversalStack.isEmpty()) {
            CategoryNode current = traversalStack.pop();
            Iterator<CategoryNode> it = current.children.iterator();
            while (it.hasNext()) {
                CategoryNode child = it.next();
                if (!child.active) {
                    // Count the nodes in the inactive subtree
                    Stack<CategoryNode> countStack = new Stack<>();
                    countStack.push(child);
                    while (!countStack.isEmpty()) {
                        CategoryNode tmp = countStack.pop();
                        removed++;
                        for (CategoryNode grand : tmp.children) {
                            countStack.push(grand);
                        }
                    }
                    // Remove the inactive child from the parent list
                    it.remove();
                } else {
                    traversalStack.push(child);
                }
            }
        }
    } catch (Exception e) {
        // In case of any unexpected error, return 0 removed nodes
        return 0;
    }
    return removed;
}

