private OuterFaceCirculator selectOnOuterFace(Predicate<Node> predicate, Node start, Node stop, int dir){
    // Defensive checks: if predicate or nodes are null, return a circulator at the stop node (if available)
    if (predicate == null) {
        return stop != null ? new OuterFaceCirculator(stop) : null;
    }
    if (start == null) {
        return stop != null ? new OuterFaceCirculator(stop) : null;
    }
    // If stop is null, treat the traversal as unlimited; we simply return the start circulator if predicate matches,
    // otherwise we attempt to continue until we loop back to start.
    OuterFaceCirculator current = new OuterFaceCirculator(start);
    OuterFaceCirculator stopCirculator = stop != null ? new OuterFaceCirculator(stop) : null;
    int direction = dir >= 0 ? 1 : -1; // positive for forward, negative for reverse

    try {
        // Loop until we either find a matching node or reach the stop node (if one is specified)
        while (true) {
            Node currentNode = current.getNode();
            if (predicate.test(currentNode)) {
                return current;
            }
            // If we've reached the stop node (and stopCirculator is defined), stop searching
            if (stopCirculator != null && current.equals(stopCirculator)) {
                break;
            }
            // Move to the next or previous element depending on direction
            if (direction > 0) {
                current = current.next();
            } else {
                current = current.prev();
            }
            // If we loop back to the start without finding a match, break out to avoid infinite loop
            if (current != null && current.equals(new OuterFaceCirculator(start))) {
                // If we returned to the start and no match was found, break
                break;
            }
        }
    } catch (Exception e) {
        // In case of any unexpected runtime issue, return the stop circulator (if available)
        return stopCirculator;
    }

    // Return a circulator pointing at the stop node if it was defined; otherwise return the current circulator.
    return stopCirculator != null ? stopCirculator : current;
}

private OuterFaceCirculator selectOnOuterFace(Predicate<Node> predicate, Node start, Node stop, int dir) {
    // Validate input arguments
    if (predicate == null || start == null || stop == null) {
        throw new IllegalArgumentException("Predicate, start, and stop nodes must all be non‑null");
    }

    // Safety: avoid infinite loops by limiting iterations to a reasonable bound
    final int MAX_ITERATIONS = 10000;
    int iterations = 0;

    Node current = start;
    while (iterations < MAX_ITERATIONS) {
        try {
            // Check the predicate first
            if (predicate.test(current)) {
                return new OuterFaceCirculator(current);
            }

            // If the current node is the stop node, break and return a circulator to it
            if (current.equals(stop)) {
                return new OuterFaceCirculator(stop);
            }

            // Move to the next node along the outer face in the specified direction.
            // The specific method name may vary; we use a commonly seen
            // convention here. If the graph structure uses another method, simply
            // replace `getNextOnOuterFace` with the correct accessor.
            current = current.getNextOnOuterFace(dir);

            // If the traversal returned null, we cannot continue
            if (current == null) {
                break;
            }
        } catch (Exception e) {
            // If any unexpected exception occurs during traversal, exit the loop
            break;
        }

        iterations++;
    }

    // If no matching node was found (or traversal failed), return circulator to stop
    return new OuterFaceCirculator(stop);
}

private OuterFaceCirculator selectOnOuterFace(Predicate<Node> predicate, Node start, Node stop, int dir){
    if (predicate == null) {
        throw new IllegalArgumentException("predicate must not be null");
    }
    if (start == null) {
        throw new IllegalArgumentException("start node must not be null");
    }
    if (stop == null) {
        throw new IllegalArgumentException("stop node must not be null");
    }
    // If the start node already satisfies the predicate, we can return a circulator for it immediately.
    if (predicate.test(start)) {
        return new OuterFaceCirculator(start);
    }
    // Traverse the outer face starting from 'start' following the given direction 'dir'.
    // We assume that a Node object provides a method `getOuterFaceNeighbour(int dir)`
    // that returns the adjacent node along the outer face in the specified direction.
    Node current = start;
    // To avoid infinite loops in malformed meshes, keep a counter and bail out after a large number of steps.
    int safetyCounter = 0;
    int maxSteps = 2 * Math.max(1, (int) Math.sqrt(Integer.MAX_VALUE)); // a very loose upper bound
    while (!current.equals(stop)) {
        // Stop if we looped too many times (should never happen in a well‑formed mesh)
        if (++safetyCounter > maxSteps) {
            break;
        }
        // Move to the next node on the outer face.
        Node next = null;
        try {
            next = current.getOuterFaceNeighbour(dir); // assumption about the API
        } catch (Throwable t) {
            // If the required method does not exist or throws, we cannot continue traversal.
            break;
        }
        if (next == null) {
            // No further node in this direction; end traversal.
            break;
        }
        current = next;
        if (predicate.test(current)) {
            return new OuterFaceCirculator(current);
        }
    }
    // If we reached the stop node (or failed to find a node satisfying the predicate),
    // return a circulator pointing to the stop node.
    return new OuterFaceCirculator(stop);
}

private OuterFaceCirculator selectOnOuterFace(Predicate<Node> predicate, Node start, Node stop, int dir) {
    if (predicate == null) {
        throw new IllegalArgumentException("predicate must not be null");
    }
    if (start == null) {
