    }
    if (stop == null) {
        throw new IllegalArgumentException("stop node must not be null");
    }

    OuterFaceCirculator circ = start.getOuterFaceCirculator(dir);

    // If start is already the stop node, return immediately
    if (circ.getNode() == stop) {
        return circ;
    }

    try {
        // Traverse until we either hit the stop node or find a node that satisfies the predicate
        while (circ.getNode() != stop) {
            Node curr = circ.getNode();
            if (predicate.test(curr)) {
                return circ;
            }
            circ = circ.next(); // advance to the next node in the given direction
        }

        // We have reached the stop node; check if it satisfies the predicate
        if (predicate.test(circ.getNode())) {
            return circ;
        }
    } catch (NullPointerException | IllegalStateException e) {
        // In case the circulator implementation throws an exception, return the stop node circulator
    }

    // If nothing was found along the path, return a circulator positioned at the stop node
    return new OuterFaceCirculator(stop, dir);
}

private OuterFaceCirculator selectOnOuterFace(Predicate<Node> predicate, Node start, Node stop, int dir) {
    // Basic validation
    if (predicate == null || start == null || stop == null) {
        throw new IllegalArgumentException("predicate, start and stop must not be null");
    }

    // In case direction is unspecified, default to 1 (clockwise)
    if (dir != 1 && dir != -1) {
        dir = 1;
    }

    Node current = start;
    try {
        // Loop until we hit the stop node or find a node matching the predicate.
        // The loop runs at least once to consider the start node itself.
        while (true) {
            if (current == stop || predicate.test(current)) {
                break;
            }
            // Assume Node provides a method to traverse along the outer face.
            // The exact method name might vary; if it throws an exception,
            // we fall back to returning a circulator to the stop node.
            try {
                current = current.getNextOnOuterFace(dir);
            } catch (Exception e) {
                // If traversal fails, stop and return a circulator to stop node
                current = stop;
                break;
            }
        }
    } catch (Exception e) {
        // Any unexpected error during traversal results in a safe return
        current = stop;
    }

    return new OuterFaceCirculator(current, dir);
}

