    ensureCapacity(length + byteLength);

    if (byteArrayValue == null) {
        // Null source array: put zero bytes
        for (int i = 0; i < byteLength; i++) {
            buffer[length + i] = 0;
        }
    } else {
        // Validate source bounds
        if ((long) byteOffset + byteLength > byteArrayValue.length) {
            throw new ArrayIndexOutOfBoundsException(
                "Requested " + byteLength + " bytes from index " + byteOffset +
                " exceeds source array length " + byteArrayValue.length);
        }
        // Copy bytes from source array
        System.arraycopy(byteArrayValue, byteOffset, buffer, length, byteLength);
    }

    // Update current length
    length += byteLength;
    return this;
}

