            // Skip static fields, as they are not part of the instance state
            if (java.lang.reflect.Modifier.isStatic(field.getModifiers())) {
                continue;
            }
            field.setAccessible(true);
            values.add(field.get(this));
        }
        return java.util.Objects.hash(values.toArray());
    } catch (IllegalAccessException e) {
        // If a field cannot be accessed, fall back to identity hash code to avoid failure
        return System.identityHashCode(this);
