protected GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph) {
    if (tour == null || graph == null) {
        throw new IllegalArgumentException("Tour and graph must not be null");
    }
    if (tour.isEmpty()) {
        // Return an empty path with zero weight
        return new GraphWalk<>(graph, new ArrayList<>(), new ArrayList<>(), 0.0);
    }

    Set<E> remaining = new HashSet<>(tour);
    List<V> vertices = new ArrayList<>();
    List<E> edges = new ArrayList<>();

    // Pick an arbitrary starting edge
    E firstEdge = remaining.iterator().next();
    V current = graph.getEdgeSource(firstEdge);
    vertices.add(current);

    while (!remaining.isEmpty()) {
        E nextEdge = null;
        for (E e : graph.edgesOf(current)) {
            if (remaining.contains(e)) {
                nextEdge = e;
                break;
            }
        }

        if (nextEdge == null) {
            throw new IllegalArgumentException("Edges in tour do not form a continuous path");
        }

        edges.add(nextEdge);
        remaining.remove(nextEdge);

        // Determine the next vertex
        V nextVertex = graph.getEdgeSource(nextEdge);
        if (nextVertex.equals(current)) {
            nextVertex = graph.getEdgeTarget(nextEdge);
        }
        current = nextVertex;
        vertices.add(current);
    }

    double weight = 0.0;
    for (E e : edges) {
        weight += graph.getEdgeWeight(e);
    }

    return new GraphWalk<>(graph, vertices, edges, weight);
}

protected GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph) {
    if (tour == null || graph == null || tour.isEmpty()) {
        return null;
    }
    // Build adjacency mapping from vertex to incident edges.
    Map<V, List<E>> adjacency = new HashMap<>();
    for (E e : tour) {
        V source = graph.getEdgeSource(e);
        V target = graph.getEdgeTarget(e);
        adjacency.computeIfAbsent(source, k -> new ArrayList<>()).add(e);
        adjacency.computeIfAbsent(target, k -> new ArrayList<>()).add(e);
    }

    // Pick a start vertex: prefer a vertex of degree 1 (path endpoint), otherwise any vertex.
    V start = null;
    for (Map.Entry<V, List<E>> entry : adjacency.entrySet()) {
        if (entry.getValue().size() == 1) {
            start = entry.getKey();
            break;
        }
    }
    if (start == null && !adjacency.isEmpty()) {
        start = adjacency.keySet().iterator().next();
    }
    if (start == null) {
        return null;
    }

    List<V> vertexList = new ArrayList<>();
    List<E> edgeList   = new ArrayList<>();
    Set<E> visited     = new HashSet<>();

    V current = start;
    vertexList.add(current);

    while (visited.size() < tour.size()) {
        List<E> candidates = adjacency.get(current);
        if (candidates == null) {
            break;
        }
        boolean advanced = false;
        for (E e : candidates) {
            if (visited.contains(e)) {
                continue;
            }
            V next = graph.getEdgeSource(e).equals(current) ? graph.getEdgeTarget(e) : graph.getEdgeSource(e);
            visited.add(e);
            edgeList.add(e);
            vertexList.add(next);
            current = next;
            advanced = true;
            break;
        }
        if (!advanced) {
            break; // no unvisited edge from current vertex
        }
    }

    if (vertexList.isEmpty() || edgeList.isEmpty()) {
        return null;
    }

    double totalWeight = 0.0;
    for (E e : edgeList) {
        try {
            totalWeight += graph.getEdgeWeight(e);
        } catch (Exception ex) {
            // If the graph does not support weights, ignore and leave weight as default.
        }
    }

    // Construct a GraphPath using JGraphT's GraphWalk implementation.
    return new GraphWalk<>(
            graph,
            vertexList,
            edgeList,
            vertexList.get(0),
            vertexList.get(vertexList.size() - 1),
            totalWeight);
}

protected GraphPath<V,E> edgeSetToTour(Set<E> tour, Graph<V,E> graph) {
    if (tour == null || graph == null) {
        throw new IllegalArgumentException("Tour and graph cannot be null");
    }
    int edgeCount = tour.size();
    if (edgeCount == 0) {
        return new SimpleGraphPath<>(graph, new ArrayList<>(), new ArrayList<>(), 0.0);
    }

    // Build adjacency map: vertex -> edges incident in the tour
    Map<V, List<E>> adjacency = new HashMap<>();
    for (E e : tour) {
        if (!graph.containsEdge(e)) {
            throw new IllegalArgumentException("Edge " + e + " is not part of the graph");
        }
        V u = graph.getEdgeSource(e);
        V v = graph.getEdgeTarget(e);
        adjacency.computeIfAbsent(u, k -> new ArrayList<>()).add(e);
        adjacency.computeIfAbsent(v, k -> new ArrayList<>()).add(e);
    }

    // Validate that each vertex has degree 2 (necessary for a tour)
    for (Map.Entry<V, List<E>> entry : adjacency.entrySet()) {
        if (entry.getValue().size() != 2) {
            throw new IllegalArgumentException("Vertex " + entry.getKey()
                    + " does not have degree 2 in the provided edge set");
        }
    }

    // Start traversal from an arbitrary vertex
    V start = adjacency.keySet().iterator().next();
    List<V> vertexList = new ArrayList<>();
    List<E> edgeList = new ArrayList<>();
    Set<E> visitedEdges = new HashSet<>();

    vertexList.add(start);
    V current = start;
    E previous = null;

    while (visitedEdges.size() < edgeCount) {
        List<E> edgesForVertex = adjacency.get(current);
        if (edgesForVertex == null) {
            throw new IllegalArgumentException("No edges found for vertex " + current);
        }

        E nextEdge = null;
        for (E e : edgesForVertex) {
            if (!visitedEdges.contains(e) && !e.equals(previous)) {
                nextEdge = e;
                break;
            }
        }

        if (nextEdge == null) {
            throw new IllegalArgumentException("Cannot find a continuation edge from vertex " + current
                    + ". The edge set does not form a single cycle.");
        }

        visitedEdges.add(nextEdge);
        edgeList.add(nextEdge);

        V nextVertex = graph.getEdgeSource(nextEdge).equals(current)
                ? graph.getEdgeTarget(nextEdge)
                : graph.getEdgeSource(nextEdge);
        vertexList.add(nextVertex);

        previous = nextEdge;
        current = nextVertex;
    }

    // Compute total weight of the tour
    double totalWeight = 0.0;
    for (E e : edgeList) {
        totalWeight += graph.getEdgeWeight(e);
    }

    return new SimpleGraphPath<>(graph, vertexList, edgeList, totalWeight);
}

