                if (countHex > 0) {
                    String hexStr = input.substring(hexStart, hexEnd);
                    try {
                        sb.append((char) Integer.parseInt(hexStr, 16));
                    } catch (NumberFormatException e) {
                        // Fallback: append raw characters
                        sb.append('x').append(hexStr);
                    }
                    i = hexEnd - 1;
                } else {
                    sb.append('x');
                }
                break;
            default:
                // Octal escape: \0-7 up to three digits
                if (charInRange(next, '0', '7')) {
                    int octStart = i;
                    int octEnd = octStart + 1;
                    int countOct = 1;
                    while (octEnd < len - (quoted ? 1 : 0)
                            && countOct < 3
                            && charInRange(input.charAt(octEnd), '0', '7')) {
                        octEnd++;
                        countOct++;
                    }
                    String octStr = input.substring(octStart, octEnd);
                    try {
                        sb.append((char) Integer.parseInt(octStr, 8));
                    } catch (NumberFormatException e) {
                        // Fallback: append raw characters
                        sb.append('\\').append(octStr);
                    }
                    i = octEnd - 1;
                } else {
                    // Unknown escape – keep the next character as is
                    sb.append(next);
                }
                break;
        }
    }

    return sb.toString();
}

/** Helper to check if a char falls within a character range. */
private boolean charInRange(char c, char min, char max) {
    return c >= min && c <= max;
}

private String unescapeId(String input){
    if (input == null) {
        return null;
    }
    int len = input.length();
    // Nothing to unescape for a string shorter than 2 characters
    if (len < 2) {
        return input;
    }

    boolean quoted = input.charAt(0) == '\"';
    StringBuilder sb = new StringBuilder();
    boolean escape = false;

    int start = quoted ? 1 : 0;
    for (int i = start; i < len; i++) {
        char c = input.charAt(i);

        if (escape) {
            // Translate escape sequences as defined by DOT
            switch (c) {
                case 'n':
                    sb.append('\n');
                    break;
                case 't':
                    sb.append('\t');
                    break;
                case 'r':
                    sb.append('\r');
                    break;
                case 'b':
                    sb.append('\b');
                    break;
                case 'f':
                    sb.append('\f');
                    break;
                case '\"':
                    sb.append('\"');
                    break;
                case '\\':
                    sb.append('\\');
                    break;
                default:
                    // Any other escaped character is taken literally
                    sb.append(c);
                    break;
            }
            escape = false;
            continue;
        }

        if (c == '\\') {
            escape = true;
            continue;
        }

        // If we are inside quotes, the final quote (at the end of the string)
        // terminates the identifier and should not be part of the output.
        if (quoted && c == '\"' && i == len - 1) {
            break;
        }

        sb.append(c);
    }

    // If the string ended with a backslash, keep it as a literal character.
    if (escape) {
        sb.append('\\');
    }

    return sb.toString();
}

