    }
    Set<Integer> bucketMin = bucketsByLabel.get(minLabel);
    if (bucketMin == null) {
        bucketMin = new HashSet<>();
        bucketsByLabel.set(minLabel, bucketMin);
    }

    if (minLabel == 0) {
        // Moving from bucket 0 to bucket 0: just clear
        bucketMin.clear();
        return;
    }

    Set<Integer> bucketZero = bucketsByLabel.get(0);
    for (Integer v : new HashSet<>(bucketMin)) { // iterate over a copy to avoid concurrent modification
        if (v == null) {
            continue;
        }
        if (v < 0 || v >= labels.size()) {
            throw new IllegalArgumentException("Vertex index out of bounds: " + v);
        }
        labels.set(v, 0);
        bucketZero.add(v);
    }
    bucketMin.clear();
}

