        targetBucket = new java.util.HashSet<>();
        bucketsByLabel.set(0, targetBucket);
    }

    // Move vertices
    Iterator<Integer> it = sourceBucket.iterator();
    while (it.hasNext()) {
        Integer v = it.next();
        // Update bucket membership
        targetBucket.add(v);
        // Update label
        if (v >= 0 && v < labels.size()) {
            labels.set(v, 0);
