public static int countOccurrencesOf(String str, String sub) {
    if (str == null || sub == null) {
        return 0;
    }
    int subLen = sub.length();
    if (subLen == 0) {
        return 0;
    }
    int count = 0;
    int fromIndex = 0;
    while (true) {
        int index = str.indexOf(sub, fromIndex);
        if (index == -1) {
            break;
        }
        count++;
        fromIndex = index + 1; // allow overlapping occurrences
    }
    return count;
}

public static int countOccurrencesOf(String str, String sub) {
    // Handle null inputs as specified
    if (str == null || sub == null) {
        return 0;
    }
    // An empty substring would lead to an infinite number of matches,
    // so for safety return 0 as an undefined case.
    if (sub.isEmpty()) {
        return 0;
    }
    int count = 0;
    int subLen = sub.length();
    int maxIndex = str.length() - subLen;
    // If the substring is longer than the string, no matches are possible
    if (maxIndex < 0) {
        return 0;
    }
    for (int i = 0; i <= maxIndex; i++) {
        if (str.regionMatches(i, sub, 0, subLen)) {
            count++;
        }
    }
    return count;
}

public static int countOccurrencesOf(String str, String sub) {
    // Return 0 if either argument is null
    if (str == null || sub == null) {
        return 0;
    }

    // If the substring to search for is empty, there's nothing to match.
    // We choose to return 0 to avoid an infinite loop.
    if (sub.isEmpty()) {
        return 0;
    }

    int count = 0;
    int index = 0;

    // Find the next occurrence of sub, starting from 'index'
    while (true) {
        int found = str.indexOf(sub, index);
        if (found == -1) {
            break;
        }
        count++;
        // Move past this occurrence to ensure non‑overlapping matches
        index = found + sub.length();
    }

    return count;
}

