protected void appendDetail(StringBuffer buffer, String fieldName, byte[] array) {
    if (buffer == null) {
        throw new IllegalArgumentException("buffer cannot be null");
    }
    // If array is null we treat it as a null value to avoid NPE; this aligns with defensive coding.
    if (array == null) {
        buffer.append(fieldName).append(": null");
        return;
    }
    buffer.append(fieldName).append(": [");
    for (int i = 0; i < array.length; i++) {
        if (i > 0) {
            buffer.append(", ");
        }
        // Append each byte as a two‑digit hexadecimal number.
        buffer.append(String.format("%02X", array[i] & 0xFF));
    }
    buffer.append("]");
}

