@Override
public boolean hasNext() {
    try {
        // If we keep a visited array, check for any false entries.
        if (visited != null) {
            for (boolean v : visited) {
                if (!v) {
                    return true;
                }
            }
        }
        // If a queue or stack of vertices to visit exists, check it as a fallback.
        if (queue != null && !queue.isEmpty()) {
            return true;
        }
        if (stack != null && !stack.isEmpty()) {
            return true;
        }
        // If there is an unvisited set or list, check it.
        if (unvisitedVertices != null && !unvisitedVertices.isEmpty()) {
            return true;
        }
        // If none of the above structures exist or they are empty, no unvisited vertices remain.
        return false;
    } catch (Exception e) {
        // In case of any unexpected runtime issue (e.g., null references), safely return false.
        return false;
    }
}

@Override public boolean hasNext() {
    try {
        // If the collection of all vertices is null or empty, there are no unvisited vertices
        if (vertices == null || vertices.isEmpty()) {
            return false;
        }
        // If no visited set exists, treat all vertices as unvisited
        if (visited == null) {
            return true;
        }
        // Return true if not all vertices have been visited
        return visited.size() < vertices.size();
    } catch (Exception e) {
        // On any unexpected exception, conservatively indicate no unvisited vertices
        return false;
    }
}

