@Override
public boolean hasNext() {
    // Since the class is designed to iterate over graph vertices,
    // we assume there is a boolean[] visited array that marks each
    // vertex as visited or not. We simply scan this array to
    // determine if any vertex is still unvisited.
    //
    // If no such array is defined, or it has length zero,
    // we defensively return false.
    try {
        if (visited == null || visited.length == 0) {
            return false;
        }
        for (boolean v : visited) {
            if (!v) {
                return true;
            }
        }
        return false;
    } catch (Exception e) {
        // In case of reflection errors or unexpected state,
        // consider that there are no unvisited vertices.
        return false;
