public static String stripFilenameExtension(String path){
    // Return null if the input is null
    if (path == null) {
        return null;
    }
    // Find the last path separator index (handles both / and \)
    int lastSeparator = Math.max(path.lastIndexOf('/'), path.lastIndexOf('\\'));
    // Find the last dot index
    int lastDot = path.lastIndexOf('.');
    // No dot found, or dot comes before the last separator (i.e., part of a directory name)
    if (lastDot == -1 || lastDot <= lastSeparator) {
        return null;
    }
    // Handle hidden files that start with a dot but have no extension
    // If the dot is at position 0 and there is no separator, treat as no extension
    if (lastDot == 0 && lastSeparator == -1) {
        return null;
    }
    // Strip the extension
    return path.substring(0, lastDot);
}

public static String stripFilenameExtension(String path) {
    // Handle null input
    if (path == null) {
        return null;
    }

    // Find the last path separator (both / and \\\\)
    int lastSlash = Math.max(path.lastIndexOf('/'), path.lastIndexOf('\\'));

    // Extract the filename part
    String baseName = path.substring(lastSlash + 1);

    // Find the last dot in the filename
    int lastDot = baseName.lastIndexOf('.');

    // No dot, or dot is the first character (hidden file), or dot is at the end (no extension)
    if (lastDot <= 0 || lastDot == baseName.length() - 1) {
        return null;
    }

    // Build the result: keep the path up to the file name, then the name without the extension
    String withoutExt = baseName.substring(0, lastDot);
    return path.substring(0, lastSlash + 1) + withoutExt;
}

