private Pair<List<Integer>, Long> computeSuffixSum(List<Integer> bounds) {
    if (bounds == null) {
        throw new IllegalArgumentException("bounds list cannot be null");
    }
    int n = bounds.size();
    List<Integer> suffixSumList = new ArrayList<>(n);
    long currentSum = 0L;
    int[] temp = new int[n];
    for (int i = n - 1; i >= 0; i--) {
        Integer value = bounds.get(i);
        if (value == null) {
            throw new IllegalArgumentException("bounds list cannot contain null elements");
        }
        currentSum += value.longValue();
        temp[i] = (int) currentSum; // may overflow, but conforms to Integer return type
    }
    for (int i = 0; i < n; i++) {
        suffixSumList.add(temp[i]);
    }
    return new Pair<>(suffixSumList, currentSum);
}

private Pair<List<Integer>, Long> computeSuffixSum(List<Integer> bounds){
    if (bounds == null){
        return new Pair<>(new ArrayList<>(), 0L);
    }
    int n = bounds.size();
    // Prepare the suffix list with the same size
    List<Integer> suffix = new ArrayList<>(Collections.nCopies(n, 0));
    long totalSum = 0L;
    long currentSuffix = 0L;
    for (int i = n - 1; i >= 0; i--){
        Integer valObj = bounds.get(i);
        long val = (valObj == null) ? 0L : valObj.longValue();
        currentSuffix += val;
        // guard against overflow when assigning to Integer
        if (currentSuffix > Integer.MAX_VALUE){
            suffix.set(i, Integer.MAX_VALUE);
        } else if (currentSuffix < Integer.MIN_VALUE){
            suffix.set(i, Integer.MIN_VALUE);
        } else {
            suffix.set(i, (int) currentSuffix);
        }
        totalSum += val;
    }
    return new Pair<>(suffix, totalSum);
}

