        } else if (running < Integer.MIN_VALUE) {
            suffixInt = Integer.MIN_VALUE;
        } else {
            suffixInt = (int) running;
        }
        suffix.add(suffixInt);
        totalSum += valLong;
    }
    Collections.reverse(suffix);
    return new Pair<>(suffix, totalSum);
}

