private void moveAllListNodes(DoublyLinkedList<E> list) {
    // Defensive check: if the source is null, identical to destination, or empty, do nothing.
    if (list == null || list == this || list.size == 0) {
        return;
    }

    // Grab first and last real nodes of the source list.
    // It is assumed that each list contains two sentinel nodes: head and tail.
    // The first real node is head.next; the last real node is tail.prev.
    final ListNodeImpl<E> srcFirst  = list.head.next;
    final ListNodeImpl<E> srcLast   = list.tail.prev;

