    // Preserve the number of nodes that will be moved.
    final int movedSize = list.size;

    // If this list is empty, simply point its sentinels to the source nodes.
    if (this.head.next == this.tail) {
        this.head.next = srcFirst;
        srcFirst.prev = this.head;
        this.tail.prev = srcLast;
        srcLast.next = this.tail;
    } else {
        // Connect the tail of this list to the first node of the source.
        final ListNodeImpl<E> thisLast = this.tail.prev;
        thisLast.next = srcFirst;
        srcFirst.prev = thisLast;

        // Connect the last node of the source to the tail sentinel of this list.
        this.tail.prev = srcLast;
        srcLast.next = this.tail;
    }

    // Clear the source list: reset its sentinels and size.
    list.head.next = list.tail;
    list.tail.prev = list.head;
    list.size = 0;

    // Update the destination list's size.
    this.size += movedSize;
}

