public static String[] split(String toSplit, String delimiter) {
    // Validate inputs: if either is null or the delimiter is empty, return null
    if (toSplit == null || delimiter == null || delimiter.isEmpty()) {
        return null;
    }
    // Find the first occurrence of the delimiter
    int index = toSplit.indexOf(delimiter);
    if (index == -1) {
        return null; // delimiter not found
    }
    // Construct and return the resulting array
    String before = toSplit.substring(0, index);
    String after = toSplit.substring(index + delimiter.length());
    return new String[] { before, after };
}

