private List<Pair<List<Pair<Integer,Integer>>, E>> computeGlobalSeparatorList() {
    // Validate graph structure
    if (adjacency == null || edges == null) {
        throw new IllegalStateException("Graph adjacency or edge set is not initialized.");
    }

    // Result list
    List<Pair<List<Pair<Integer,Integer>>, E>> result = new ArrayList<>();

    // Helper to obtain canonical pair representation
    java.util.function.BiFunction<Integer, Integer, Pair<Integer, Integer>> canonical =
            (a, b) -> {
                int min = Math.min(a, b);
                int max = Math.max(a, b);
                return new Pair<>(min, max);
            };

    // Convert Set<E> to List<E> for index-based subset generation
    List<E> edgeList = new ArrayList<>(edges);

    for (E e : edgeList) {
        // Get endpoints of the current edge (expecting E to be Pair<Integer,Integer>)
        int[] endpoints;
        try {
            @SuppressWarnings("unchecked")
            Pair<Integer, Integer> pair = (Pair<Integer, Integer>) e;
            endpoints = new int[]{pair.getFirst(), pair.getSecond()};
        } catch (ClassCastException ex) {
            // Edge type does not support endpoint extraction; skip this edge
            continue;
        }
        int u = endpoints[0];
        int v = endpoints[1];

        // Determine neighbor edges (exclude the edge itself)
        List<E> neighborEdges = new ArrayList<>();
        for (E f : edgeList) {
            if (f.equals(e)) {
                continue;
            }
            int[] ep;
            try {
                @SuppressWarnings("unchecked")
                Pair<Integer, Integer> pairF = (Pair<Integer, Integer>) f;
                ep = new int[]{pairF.getFirst(), pairF.getSecond()};
            } catch (ClassCastException ex) {
                continue;
            }
            int a = ep[0], b = ep[1];
            if (a == u || a == v || b == u || b == v) {
                neighborEdges.add(f);
            }
        }

        int n = neighborEdges.size();
        // No neighbors -> no separators
        if (n == 0) {
            continue;
        }

        // Find all separating subsets
        List<Set<E>> separators = new ArrayList<>();
        for (int mask = 1; mask < (1 << n); mask++) {
            Set<E> removed = new HashSet<>();
            for (int i = 0; i < n; i++) {
                if ((mask & (1 << i)) != 0) {
                    removed.add(neighborEdges.get(i));
                }
            }
            // Test connectivity between u and v after removing edges in 'removed'
            if (!isConnected(u, v, removed, canonical)) {
                separators.add(removed);
            }
        }

        // Minimize separators: keep only minimal ones
        List<Set<E>> minimalSeparators = new ArrayList<>();
        loop:
        for (Set<E> s : separators) {
            for (Set<E> t : separators) {
                if (t == s) continue;
                if (t.containsAll(s)) {
                    // s is not minimal
                    continue loop;
                }
            }
            minimalSeparators.add(s);
        }

        // Convert each separator set to list of Pair<Integer,Integer>
        for (Set<E> sepSet : minimalSeparators) {
            List<Pair<Integer, Integer>> separatorList = new ArrayList<>();
            for (E f : sepSet) {
                @SuppressWarnings("unchecked")
                Pair<Integer, Integer> pf = (Pair<Integer, Integer>) f;
                separatorList.add(pf);
            }
            result.add(new Pair<>(separatorList, e));
        }
    }

    return result;
}

/**
 * Helper method to test whether two vertices are still connected after removing
 * a set of edges. The graph is represented by 'adjacency' and edge removals are
 * given as a set of edge objects (E).  Edges are considered undirected.
 */
private boolean isConnected(int start, int target,
                            Set<E> removedEdges,
                            java.util.function.BiFunction<Integer, Integer, Pair<Integer, Integer>> canonical) {
    java.util.Set<Integer> visited = new java.util.HashSet<>();
    java.util.Queue<Integer> queue = new java.util.LinkedList<>();
    visited.add(start);
    queue.offer(start);
    while (!queue.isEmpty()) {
        int node = queue.poll();
        if (node == target) {
            return true;
        }
        java.util.Set<Integer> neighbors = adjacency.getOrDefault(node, java.util.Collections.emptySet());
        for (int nb : neighbors) {
            if (visited.contains(nb)) {
                continue;
            }
            // Check if the edge between node and nb is removed
            @SuppressWarnings("unchecked")
            Pair<Integer, Integer> edge = (Pair<Integer, Integer>) canonical.apply(node, nb);
            if (removedEdges.contains(edge)) {
                continue;
            }
            visited.add(nb);
            queue.offer(nb);
        }
    }
    return false;
}

