public static void selectRow(int row, JTable table, JScrollPane pane) {
    if (table == null || pane == null) {
        return;
    }
    int totalRows = table.getRowCount();
    if (row < 0 || row >= totalRows) {
        return;
    }
    javax.swing.SwingUtilities.invokeLater(() -> {
        table.setRowSelectionInterval(row, row);
        java.awt.Rectangle rect = table.getCellRect(row, 0, true);
        pane.getViewport().scrollRectToVisible(rect);
        javax.swing.Timer timer = new javax.swing.Timer(50, e -> {
            table.repaint();
        });
        timer.setRepeats(false);
        timer.start();
    });
}

public static void selectRow(int row, JTable table, JScrollPane pane) {
    // Validate inputs
    if (table == null || pane == null) {
        return;
    }
    int rowCount = table.getRowCount();
    if (row < 0 || row >= rowCount) {
        return;
    }

    Runnable selectAndScroll = () -> {
        // Select the specified row
        table.setRowSelectionInterval(row, row);
        // Ensure the row is visible in the viewport
        Rectangle rect = table.getCellRect(row, 0, true);
        if (rect != null) {
            table.scrollRectToVisible(rect);
        }

        // Delay repainting so that the UI has a chance to paint the selection
        javax.swing.Timer repaintTimer = new javax.swing.Timer(100, e -> table.repaint());
        repaintTimer.setRepeats(false);
        repaintTimer.start();
    };

    // Execute the action on the EDT
    if (javax.swing.SwingUtilities.isEventDispatchThread()) {
        selectAndScroll.run();
    } else {
        javax.swing.SwingUtilities.invokeLater(selectAndScroll);
    }
}

public static void selectRow(int row, JTable table, JScrollPane pane) {
    // Validate inputs
    if (table == null || pane == null) {
        return;
    }
    int rowCount = table.getRowCount();
    if (rowCount == 0 || row < 0 || row >= rowCount) {
        return;
    }

    // Select only the specified row
    try {
        table.setRowSelectionInterval(row, row);
    } catch (Exception e) {
        // Ignored – selection failure should not crash the caller
    }

    // Ensure a column is selected (or default to column 0)
    int column = table.getSelectedColumn();
    if (column < 0) {
        column = 0;
    }

    // Scroll the cell into view
    Rectangle cellRect = table.getCellRect(row, column, true);
    if (cellRect != null) {
        table.scrollRectToVisible(cellRect);
    }

    // Request focus and delay repaint to allow the UI to update
    table.requestFocusInWindow();
    SwingUtilities.invokeLater(() -> {
        // Small delay via a one-shot timer to ensure proper painting
        new Timer(20, e -> {
            ((Timer) e.getSource()).stop();
            table.repaint();
        }).start();
    });
}

