    if (count < 0) {
        return false;
    }
    // If count is greater than either array length, they can't match.
    if (a.length < count || b.length < count) {
        return false;
    }
    // Compare the first 'count' bytes.
    for (int i = 0; i < count; i++) {
        if (a[i] != b[i]) {
            return false;
        }
    }
    return true;
}

public static boolean arrayequals(byte[] a, byte[] b, int count){
    if (a == null || b == null) {
        throw new IllegalArgumentException("arrays must not be null");
    }
    if (count < 0) {
        throw new IllegalArgumentException("count must be non‑negative");
    }
    if (a.length < count || b.length < count) {
        throw new IllegalArgumentException("array length must be at least count");
    }
    for (int i = 0; i < count; i++) {
        if (a[i] != b[i]) {
            return false;
        }
    }
    return true;
}

public void abbreviate(final int nameStart, final StringBuffer buf){
    if (buf == null) {
        throw new IllegalArgumentException("Buffer must not be null");
    }
    if (nameStart < 0) {
        throw new IllegalArgumentException("nameStart cannot be negative");
    }
    // Assume the enclosing class has a String field `name` that holds the full name.
    String fullName = this.name;
    if (fullName == null || fullName.isEmpty()) {
        return;
    }
    if (nameStart >= fullName.length()) {
        return;
    }
    int i = nameStart;
    // Skip leading whitespace to find the start of the next word.
    while (i < fullName.length() && Character.isWhitespace(fullName.charAt(i))) {
        i++;
    }
    if (i >= fullName.length()) {
        return;
    }
    // Append the first character of the next word.
    buf.append(fullName.charAt(i));
    // Advance through the rest of the word.
    while (i < fullName.length() && !Character.isWhitespace(fullName.charAt(i))) {
        i++;
    }
    // If there is more text after this word, indicate truncation with a period.
    if (i < fullName.length()) {
        buf.append('.');
    }
}

public void abbreviate(final int nameStart, final StringBuffer buf) {
    // Assume the containing class has a field named 'name' holding the full identifier.
    if (buf == null) {
        throw new IllegalArgumentException("Buffer must not be null");
    }
    if (nameStart < 0) {
        throw new IllegalArgumentException("nameStart must be non-negative");
    }

    // Retrieve the full name from the class field.
    // This method expects that the instance has a String field called 'name'.
    final String fullName;
    try {
        java.lang.reflect.Field f = this.getClass().getDeclaredField("name");
        f.setAccessible(true);
        Object val = f.get(this);
        if (!(val instanceof String)) {
            return; // nothing to abbreviate if the field is not a String
        }
        fullName = (String) val;
    } catch (NoSuchFieldException | IllegalAccessException e) {
        // If the field doesn't exist or is inaccessible, do nothing.
        return;
    }

    if (fullName == null) {
        return;
    }

    final int len = fullName.length();
    if (nameStart >= len) {
        return; // nothing to abbreviate
    }

    // Build abbreviation: abbreviate each component separated by '.' to its first letter,
    // except the last component which is kept whole.
    int idx = nameStart;
    StringBuilder abbreviation = new StringBuilder();

    while (idx < len) {
        int nextDot = fullName.indexOf('.', idx);
        if (nextDot == -1) { // last segment
            abbreviation.append(fullName.substring(idx));
            break;
        } else {
            // Append the first letter of the current segment and a dot.
            abbreviation.append(fullName.charAt(idx));
            abbreviation.append('.');
            idx = nextDot + 1;
        }
    }

    buf.append(abbreviation.toString());
}

public void abbreviate(final int nameStart, final StringBuffer buf) {
    if (buf == null) {
        throw new IllegalArgumentException("Buffer cannot be null");
    }
    // Assume the class has a field named 'name' holding the full name string.
    if (this.name == null) {
        throw new IllegalStateException("The 'name' field is null");
    }
    if (nameStart < 0 || nameStart > this.name.length()) {
        throw new IllegalArgumentException("nameStart out of bounds");
    }

    String remaining = this.name.substring(nameStart);
    if (remaining.isEmpty()) {
        // Nothing to abbreviate
        return;
    }

    String[] parts = remaining.split("\\.");
    StringBuilder abbreviation = new StringBuilder();
    for (int i = 0; i < parts.length; i++) {
        String part = parts[i];
        if (part.isEmpty()) {
            continue;
        }
        if (i < parts.length - 1) {
            abbreviation.append(part.charAt(0)).append('.');
        } else {
            abbreviation.append(part);
        }
    }
    buf.append(abbreviation);
}

public void abbreviate(final int nameStart, final StringBuffer buf) {
    if (buf == null) {
        return;
    }
    int length = buf.length();
    if (nameStart < 0 || nameStart > length) {
        // nothing to do
        return;
    }

    String fullText = buf.substring(nameStart);
    StringBuilder abbreviation = new StringBuilder();
    boolean startOfWord = true;

    for (int i = 0; i < fullText.length(); i++) {
        char c = fullText.charAt(i);
        if (Character.isLetterOrDigit(c)) {
            if (!startOfWord && abbreviation.length() > 0) {
                // separate different words with a dot
                abbreviation.append('.');
            }
            abbreviation.append(c);
            startOfWord = false;
        } else {
            startOfWord = true;
        }
    }

    buf.append(abbreviation.toString());
}

public void abbreviate(final int nameStart, final StringBuffer buf) {
    if (buf == null) {
        throw new IllegalArgumentException("Buffer cannot be null");
    }

    // Attempt to obtain the name to abbreviate.  The class is expected to have a
    // String field named `name`.  If such a field does not exist the code will
    // not compile; this is intentional as the method is meant to illustrate
    // abbreviation logic.
    final String name = this.name;
    if (name == null || name.isEmpty()) {
        return;
    }

    if (nameStart < 0 || nameStart >= name.length()) {
        return; // nothing to abbreviate
    }

    boolean startOfWord = true;
    for (int i = nameStart; i < name.length(); i++) {
        final char ch = name.charAt(i);

        // Treat whitespace and selected punctuation as word separators.
        if (Character.isWhitespace(ch) || ch == '-' || ch == '_' || ch == '.') {
            startOfWord = true;
            continue;
        }

        if (startOfWord) {
            buf.append(Character.toUpperCase(ch)).append('.');
            startOfWord = false;
        }
    }
}

