private static <V,E> boolean isClique(Graph<V,E> graph, Set<V> vertices) {
    if (graph == null || vertices == null) {
        throw new IllegalArgumentException("Graph and vertex set must not be null");
    }
    int size = vertices.size();
    if (size <= 1) {
        return true; // empty or single-element set is trivially a clique
    }
    java.util.List<V> list = new java.util.ArrayList<>(vertices);
    for (int i = 0; i < list.size(); i++) {
        V u = list.get(i);
        for (int j = i + 1; j < list.size(); j++) {
            V v = list.get(j);
            // Check for an edge in either direction (handles undirected graphs where getEdge may be order-sensitive)
            if (graph.getEdge(u, v) == null && graph.getEdge(v, u) == null) {
                return false; // missing edge => not a clique
            }
        }
    }
    return true; // all pairs are connected
}

private static <V, E> boolean isClique(Graph<V, E> graph, Set<V> vertices) {
    if (graph == null) {
        throw new IllegalArgumentException("graph must not be null");
    }
    if (vertices == null) {
        throw new IllegalArgumentException("vertices must not be null");
    }
    if (vertices.size() <= 1) {
        return true;
    }
    // Ensure all vertices belong to the graph
    for (V v : vertices) {
        if (v == null || !graph.containsVertex(v)) {
            return false;
        }
    }
    // Check that every pair of distinct vertices is adjacent
    for (V v1 : vertices) {
        for (V v2 : vertices) {
            if (v1.equals(v2)) {
                continue;
            }
            if (!graph.containsEdge(v1, v2)) {
                return false;
            }
        }
    }
    return true;
}

private static <V,E> boolean isClique(Graph<V,E> graph, Set<V> vertices) {
    if (graph == null || vertices == null) {
        throw new IllegalArgumentException("Graph and vertex set must not be null");
    }
    // A null or single vertex set is a trivial clique
    if (vertices.size() <= 1) {
        return true;
    }
    // Ensure all vertices belong to the graph
    for (V v : vertices) {
        if (!graph.containsVertex(v)) {
            return false;
        }
    }
    // For every unordered pair of distinct vertices, check adjacency
    for (V v1 : vertices) {
        for (V v2 : vertices) {
            if (v1 == v2 || v1.equals(v2)) {
                continue; // Skip self-pairs or duplicates
            }
            if (graph.getEdge(v1, v2) == null) {
                return false; // Edge missing, not a clique
            }
        }
    }
    return true; // All pairs are connected
}

private static <V,E> boolean isClique(Graph<V,E> graph, Set<V> vertices) {
    if (graph == null || vertices == null) {
        throw new IllegalArgumentException("Graph and vertex set must not be null");
    }
    // Ensure all vertices are part of the graph
    for (V v : vertices) {
        if (!graph.containsVertex(v)) {
            throw new IllegalArgumentException("Vertex not present in the graph: " + v);
        }
    }
    int n = vertices.size();
    if (n <= 1) {
        return true; // empty or single vertex is a clique
    }
    Object[] arr = vertices.toArray();
    for (int i = 0; i < n; i++) {
        @SuppressWarnings("unchecked")
        V vi = (V) arr[i];
        for (int j = i + 1; j < n; j++) {
            @SuppressWarnings("unchecked")
            V vj = (V) arr[j];
            if (!graph.containsEdge(vi, vj) && !graph.containsEdge(vj, vi)) {
                return false;
            }
        }
    }
    return true;
}

private static <V,E> boolean isClique(Graph<V,E> graph, Set<V> vertices) {
    if (graph == null) {
        throw new IllegalArgumentException("Graph must not be null");
    }
    if (vertices == null) {
        throw new IllegalArgumentException("Vertex set must not be null");
    }
    // A set containing 0 or 1 vertex is trivially a clique
    if (vertices.size() < 2) {
        return true;
    }

    // Convert to array for indexed access
    V[] verts = (V[]) vertices.toArray(new Object[0]); // type erasure workaround
    int n = verts.length;
    try {
        for (int i = 0; i < n - 1; i++) {
            V vi = verts[i];
            if (vi == null) {
                throw new IllegalArgumentException("Vertex set contains null");
            }
            for (int j = i + 1; j < n; j++) {
                V vj = verts[j];
                if (vj == null) {
                    throw new IllegalArgumentException("Vertex set contains null");
                }
                if (!graph.containsEdge(vi, vj)) {
                    return false;
                }
            }
        }
    } catch (RuntimeException e) {
        // Wrap any unexpected runtime exception to preserve message
        throw new IllegalStateException("Error while checking clique property", e);
    }
    return true;
}

private List<Integer> computeLowerBounds(List<K> keys){
    List<Integer> result = new ArrayList<>();
    if (keys == null || keys.isEmpty()){
        return result;
    }
    List<K> sorted = new ArrayList<>(keys);
    try{
        sorted.sort(null);
    } catch (ClassCastException e){
        throw new IllegalArgumentException("Keys must be comparable", e);
    }
    for (K key : keys){
        if (key == null){
            result.add(-1);
            continue;
        }
        int insertionIndex = lowerBoundIndex(key, sorted);
        int lowerIdx = insertionIndex - 1;
        if (lowerIdx < 0){
            result.add(-1);
        } else {
            K lowerKey = sorted.get(lowerIdx);
            if (lowerKey instanceof Integer){
                result.add((Integer) lowerKey);
            } else {
                result.add(-1);
            }
        }
    }
    return result;
}

private int lowerBoundIndex(K target, List<K> sorted){
    int low = 0;
    int high = sorted.size();
    while (low < high){
        int mid = (low + high) >>> 1;
        @SuppressWarnings("unchecked")
        Comparable<K> cmp = (Comparable<K>) sorted.get(mid);
        if (cmp.compareTo(target) < 0){
            low = mid + 1;
        } else {
            high = mid;
        }
    }
    return low;
}

private List<Integer> computeLowerBounds(List<K> keys){
    List<Integer> result = new ArrayList<>();
    if (keys == null) {
        return result;
    }
    TreeSet<Integer> sorted = new TreeSet<>();
    // Populate sorted set, ignoring nulls and non‑Integer elements
    for (K k : keys) {
        if (k == null) {
            continue;
        }
        try {
            sorted.add((Integer) (Object) k);
        } catch (ClassCastException e) {
            // ignore non‑Integer elements
        }
    }
    // Compute predecessor for each key
    for (K k : keys) {
        if (k == null) {
            result.add(Integer.MIN_VALUE);
            continue;
        }
        try {
            Integer keyInt = (Integer) (Object) k;
            Integer lower = sorted.lower(keyInt);
            result.add(lower != null ? lower : Integer.MIN_VALUE);
        } catch (ClassCastException e) {
            result.add(Integer.MIN_VALUE);
        }
    }
    return result;
}

private List<Integer> computeLowerBounds(List<K> keys) {
    List<Integer> bounds = new ArrayList<>();
    if (keys == null || keys.isEmpty()) {
        return bounds;
    }
    // Create a sorted copy of the keys
    List<K> sorted = new ArrayList<>(keys);
    try {
        sorted.sort(Comparator.naturalOrder());
    } catch (ClassCastException e) {
        // If the keys are not comparable, return Integer.MIN_VALUE for each key
        for (int i = 0; i < keys.size(); i++) {
            bounds.add(Integer.MIN_VALUE);
        }
        return bounds;
    }
    // Map each key to the index of its maximum lower bound in the sorted list
    Map<K, Integer> lowerBoundIndex = new HashMap<>();
    for (int i = 0; i < sorted.size(); i++) {
        K current = sorted.get(i);
        // The maximum lower bound for this key is the index of the previous element
        int lowerIndex = (i > 0) ? i - 1 : -1;
        // For duplicate keys, keep the first lower bound encountered
        lowerBoundIndex.putIfAbsent(current, lowerIndex);
    }
    // Build the result list preserving the original order
    for (K key : keys) {
        bounds.add(lowerBoundIndex.getOrDefault(key, Integer.MIN_VALUE));
    }
    return bounds;
}

private List<Integer> computeLowerBounds(List<K> keys){
    if (keys == null) {
        throw new IllegalArgumentException("Input keys list cannot be null");
    }
    List<Integer> lowerBounds = new ArrayList<>(keys.size());
    // Use a simple O(n^2) approach for clarity and robustness
    for (K key : keys) {
        Integer bound = null;
        if (key == null) {
            lowerBounds.add(bound);
            continue;
        }
        try {
            Integer keyVal = (Integer) key; // assume K is Integer or a subtype
            Integer maxLower = null;
            for (K other : keys) {
                if (other == null || other == key) {
                    continue;
                }
                Integer otherVal = (Integer) other;
                if (otherVal < keyVal) {
                    if (maxLower == null || otherVal > maxLower) {
                        maxLower = otherVal;
                    }
                }
            }
            bound = maxLower;
        } catch (ClassCastException e) {
            // If the elements are not Integer, we can't compute bounds
            bound = null;
        }
        lowerBounds.add(bound);
    }
    return lowerBounds;
}

private List<Integer> computeLowerBounds(List<K> keys) {
    List<Integer> lowerBounds = new ArrayList<>();
    if (keys == null) {
        return lowerBounds;
    }

    // Collect all integer keys into a separate list for sorting and searching
    List<Integer> integerKeys = new ArrayList<>();
    // Keep a mapping from original index to the integer value (or null if not an Integer)
    List<Integer> originalValues = new ArrayList<>();
    for (K key : keys) {
        if (key instanceof Integer) {
            Integer val = (Integer) key;
            integerKeys.add(val);
            originalValues.add(val);
        } else {
            // Non-integer key – we cannot compute a numerical lower bound
            // Mark as null so that result will be null for this position
            originalValues.add(null);
        }
    }

    // Sort the integer keys for binary search
    if (!integerKeys.isEmpty()) {
        integerKeys.sort(Integer::compareTo);
    }

    // For each original key, compute the maximum lower bound
    for (Integer val : originalValues) {
        if (val == null) {
            // Non-numeric key – no lower bound can be computed
            lowerBounds.add(null);
            continue;
        }

        // Binary search for the position of val
        int idx = Collections.binarySearch(integerKeys, val);
        if (idx >= 0) {
            // Exact match found – the value itself is the maximum lower bound
            lowerBounds.add(integerKeys.get(idx));
        } else {
            // No exact match; binarySearch returns (-(insertion point) - 1)
            int insertionPoint = -idx - 1;
            if (insertionPoint == 0) {
                // All values in the list are greater than val – no lower bound exists
                lowerBounds.add(null);
            } else {
                // The largest value less than val is at insertionPoint - 1
                lowerBounds.add(integerKeys.get(insertionPoint - 1));
            }
        }
    }

    return lowerBounds;
}

private void pop(final String descriptor) {
    if (descriptor == null) {
        throw new IllegalArgumentException("Descriptor cannot be null");
    }
    int idx = 0;
    // Detect whether descriptor is a method descriptor
    if (!descriptor.isEmpty() && descriptor.charAt(0) == '(') {
        // Skip '('
        idx++;
        // Pop argument types
        while (idx < descriptor.length() && descriptor.charAt(idx) != ')') {
            idx = consumeTypeAndPop(descriptor, idx);
        }
        if (idx >= descriptor.length() || descriptor.charAt(idx) != ')') {
            throw new IllegalArgumentException("Invalid method descriptor: missing ')'");
        }
        // Skip ')', return type is ignored
        idx++;
    }
    // If not a method descriptor, or after method arguments, process remaining type descriptor
    while (idx < descriptor.length()) {
        idx = consumeTypeAndPop(descriptor, idx);
    }
}

/* Helper to consume a single type descriptor starting at index and pop the corresponding type from the stack.
   Returns the index immediately after the consumed type descriptor. */
private int consumeTypeAndPop(final String descriptor, int idx) {
    if (idx >= descriptor.length()) {
        throw new IllegalArgumentException("Unexpected end of descriptor");
    }
    char c = descriptor.charAt(idx);
    switch (c) {
        case 'B': case 'C': case 'F': case 'I': case 'S': case 'Z':
            popSlot();
            return idx + 1;
        case 'J': case 'D':
            // Long and double take two slots
            popSlot();
            popSlot();
            return idx + 1;
        case '[':
            idx++; // consume '['
            // Consume element type of the array
            while (idx < descriptor.length() && descriptor.charAt(idx) == '[') {
                idx++; // consume additional '[' for multi-dimensional arrays
            }
            if (idx >= descriptor.length()) {
                throw new IllegalArgumentException("Invalid descriptor: incomplete array type");
            }
            if (descriptor.charAt(idx) == 'L') {
                int semicolon = descriptor.indexOf(';', idx);
                if (semicolon == -1) {
                    throw new IllegalArgumentException("Invalid descriptor: missing ';' for object type");
                }
                idx = semicolon + 1; // consume until ';'
            } else {
                idx++; // primitive component
            }
            // The array itself occupies one slot on the stack
            popSlot();
            return idx;
        case 'L':
            int semicolon = descriptor.indexOf(';', idx);
            if (semicolon == -1) {
                throw new IllegalArgumentException("Invalid descriptor: missing ';' for object type");
            }
            popSlot();
            return semicolon + 1;
        default:
            throw new IllegalArgumentException("Unknown descriptor character: " + c);
    }
}

/* Pops the top element from the output frame stack. Handles stack underflow gracefully. */
private void popSlot() {
    try {
        outputFrameStack.removeLast();
    } catch (NoSuchElementException e) {
        throw new IllegalStateException("Attempted to pop from an empty stack", e);
    }
}

private void pop(final String descriptor){
    if (descriptor == null || descriptor.isEmpty()){
        throw new IllegalArgumentException("Descriptor must not be null or empty");
    }
    int len = descriptor.length();
    int i = 0;
    java.lang.Runnable popOne = () -> {
        try {
            outputStack.pop();
        } catch (java.util.NoSuchElementException e){
            throw new IllegalStateException("Attempted to pop from an empty stack", e);
        }
    };
    if (descriptor.charAt(0) == '('){
        i = 1; // skip '('
        while (i < len && descriptor.charAt(i) != ')'){
            char c = descriptor.charAt(i);
            if (c == '['){
                // consume array dimensions
                while (i < len && descriptor.charAt(i) == '['){
                    i++;
                }
                if (i >= len){
                    throw new IllegalArgumentException("Malformed descriptor: array dimension");
                }
                // consume element type
                if (descriptor.charAt(i) == 'L'){
                    int sem = descriptor.indexOf(';', i + 1);
                    if (sem == -1){
                        throw new IllegalArgumentException("Malformed descriptor: object type missing ';'");
                    }
                    i = sem + 1;
                } else {
                    i++; // primitive
                }
                popOne.run();
            } else if (c == 'L'){
                int sem = descriptor.indexOf(';', i + 1);
                if (sem == -1){
                    throw new IllegalArgumentException("Malformed descriptor: object type missing ';'");
                }
                i = sem + 1;
                popOne.run();
            } else if ("BCDFIJSZV".indexOf(c) != -1){
                i++;
                popOne.run();
            } else {
                throw new IllegalArgumentException("Unknown descriptor character: " + c);
            }
        }
        if (i >= len || descriptor.charAt(i) != ')'){
            throw new IllegalArgumentException("Malformed method descriptor: missing ')'");
        }
        // skip return type after ')'
    } else {
        while (i < len){
            char c = descriptor.charAt(i);
            if (c == '['){
                while (i < len && descriptor.charAt(i) == '['){
                    i++;
                }
                if (i >= len){
                    throw new IllegalArgumentException("Malformed descriptor: array dimension");
                }
                if (descriptor.charAt(i) == 'L'){
                    int sem = descriptor.indexOf(';', i + 1);
                    if (sem == -1){
                        throw new IllegalArgumentException("Malformed descriptor: object type missing ';'");
                    }
                    i = sem + 1;
                } else {
                    i++;
                }
                popOne.run();
            } else if (c == 'L'){
                int sem = descriptor.indexOf(';', i + 1);
                if (sem == -1){
                    throw new IllegalArgumentException("Malformed descriptor: object type missing ';'");
                }
                i = sem + 1;
                popOne.run();
            } else if ("BCDFIJSZV".indexOf(c) != -1){
                i++;
