private List<Integer> computeUpperBounds(List<K> keys){
    List<Integer> bounds = new ArrayList<>();
    if (keys == null || keys.isEmpty()) {
        return bounds;
    }
    int n = keys.size();
    for (int i = 0; i < n; i++) {
        bounds.add(0);
    }
    for (int i = 0; i < n; i++) {
        K base = keys.get(i);
        if (base == null) {
            bounds.set(i, 0);
            continue;
        }
        int count = 0;
        for (int j = 0; j < n; j++) {
            if (i == j) {
                continue;
            }
            K other = keys.get(j);
            if (other == null) {
                continue;
            }
            int comparison = 0;
            try {
                // Try natural ordering if K implements Comparable
                Comparable comp = (Comparable) base;
                comparison = comp.compareTo(other);
            } catch (Exception e) {
                // Fallback to hashCode comparison
                comparison = Integer.compare(base.hashCode(), other.hashCode());
            }
            if (comparison < 0) {
                count++;
            }
        }
        bounds.set(i, count);
    }
    return bounds;
}

private List<Integer> computeUpperBounds(List<K> keys){
    if (keys == null) {
        throw new IllegalArgumentException("keys list cannot be null");
    }
    List<Integer> upperBounds = new ArrayList<>(keys.size());
    for (K key : keys) {
        if (key == null) {
            upperBounds.add(Integer.MIN_VALUE);
            continue;
        }
        try {
            int bound = key.hashCode();
            if (bound == Integer.MAX_VALUE) {
                upperBounds.add(Integer.MAX_VALUE);
            } else {
                upperBounds.add(bound + 1);
            }
        } catch (Exception e) {
            upperBounds.add(Integer.MIN_VALUE);
        }
    }
    return upperBounds;
}

