    }

    // Build the resulting string
    StringBuilder sb = new StringBuilder();
    if (absolute) {
        sb.append("/");
    }
    Iterator<String> it = parts.iterator();
    while (it.hasNext()) {
        sb.append(it.next());
        if (it.hasNext()) {
            sb.append("/");
        }
    }
    String result = sb.toString();

    // If absolute path resolves to nothing, return root "/"
    if (absolute && result.isEmpty()) {
        result = "/";
    }
    return result;
}

public static String applyRelativePath(String path, String relativePath) {
    // Handle null inputs gracefully
    if (path == null) {
        return relativePath;
    }
    if (relativePath == null || relativePath.isEmpty()) {
        return path;
    }

    // Determine if the base path is absolute (starts with '/')
    boolean isAbsoluteBase = path.startsWith("/");
    // Split the base path into its components, ignoring empty parts and single dots
    ArrayList<String> segments = new ArrayList<>();
    for (String part : path.split("/")) {
        if (part.isEmpty() || part.equals(".")) {
            continue;
        }
        segments.add(part);
    }

    // Process each component of the relative path
    for (String part : relativePath.split("/")) {
        if (part.isEmpty() || part.equals(".")) {
            continue; // No effect
        }
        if (part.equals("..")) {
            if (!segments.isEmpty()) {
                // Only pop a segment if the path is not already at the root
                segments.remove(segments.size() - 1);
            } else {
                // If already at root and path is absolute, stay at root
                // If path is relative, do nothing (cannot go above start)
                continue;
            }
        } else {
            // Normal directory or file name
            segments.add(part);
        }
    }

    // Reconstruct the resolved path
    StringBuilder result = new StringBuilder();
    if (isAbsoluteBase) {
        result.append('/');
    }
    for (int i = 0; i < segments.size(); i++) {
        if (i > 0) {
            result.append('/');
        }
        result.append(segments.get(i));
    }

    // Ensure that the root path "/" is represented correctly
    String finalPath = result.toString();
    if (finalPath.isEmpty() && isAbsoluteBase) {
        finalPath = "/";
    }

    return finalPath;
}

