static String[] toNoNullStringArray(Object[] array) {
    if (array == null) {
        return null;
    }

    int nullCount = 0;
    for (Object o : array) {
        if (o == null) {
            nullCount++;
        }
    }

    if (nullCount == 0) {
        // array has no nulls – we can safely treat it as a String array
        @SuppressWarnings("unchecked")
        String[] stringArray = (String[]) array;
        return stringArray;
    }

    // Build a new array that excludes null entries
    int nonNullSize = array.length - nullCount;
    String[] result = new String[nonNullSize];
    int pos = 0;
    for (Object o : array) {
        if (o != null) {
            result[pos++] = String.valueOf(o);
        }
    }
    return result;
}

static String[] toNoNullStringArray(Object[] array){
    // If the input is null, return an empty array to avoid NPE downstream.
    if (array == null) {
        return new String[0];
    }

    // Count non‑null values to size the result array appropriately.
    int count = 0;
    for (Object obj : array) {
        if (obj != null) {
            count++;
        }
    }

    // If there are no elements or the original array already contains no nulls
    // and is a String[] we can return it directly.  This also preserves the
    // original array reference when no changes are needed.
    if (count == array.length && array instanceof String[]) {
        return (String[]) array;
    }

    // Build a new array with the non‑null elements.
    String[] result = new String[count];
    int idx = 0;
    for (Object obj : array) {
        if (obj != null) {
            // If the element is already a String we cast it, otherwise use its
            // string representation via toString().
            result[idx++] = (obj instanceof String) ? (String) obj : obj.toString();
        }
    }
    return result;
}

