public static int indexOfExtension(String filename) {
    if (filename == null) {
        return -1;
    }
    // Find the last path separator (handles both Unix '/' and Windows '\\')
    int lastSeparator = Math.max(filename.lastIndexOf('/'), filename.lastIndexOf('\\'));
    // Find the last dot in the string
    int dotIndex = filename.lastIndexOf('.');
    // Return the dot index only if it occurs after the last separator
    return (dotIndex > lastSeparator) ? dotIndex : -1;
}

public static int indexOfExtension(String filename){
    if (filename == null) {
        return -1;
    }
    int dotIndex = filename.lastIndexOf('.');
    if (dotIndex == -1) {
        return -1;
    }
    int lastSlash  = filename.lastIndexOf('/');
    int lastBack   = filename.lastIndexOf('\\');
    int lastSep    = Math.max(lastSlash, lastBack);
    if (lastSep > dotIndex) {
        return -1;
    }
    return dotIndex;
}

public static int indexOfExtension(String filename) {
    if (filename == null) {
        return -1;
    }

    // Find the last dot in the filename
    int dotIndex = filename.lastIndexOf('.');
    if (dotIndex == -1) {
        return -1; // No dot found
    }

    // Find the last path separator (handles both Unix '/' and Windows '\\')
    int lastSeparatorIndex = Math.max(filename.lastIndexOf('/'), filename.lastIndexOf('\\'));

    // If a separator is found after the dot, then the dot is part of a directory name
    if (lastSeparatorIndex > dotIndex) {
        return -1;
    }

    // The dot is after the last separator, so it is the extension separator
    return dotIndex;
}

public static int indexOfExtension(String filename){
    // Return -1 for null input
    if (filename == null) {
        return -1;
    }

    // Locate the last dot in the string
    int dotIdx = filename.lastIndexOf('.');
    if (dotIdx == -1) {
        return -1; // No dot means no extension
    }

    // Find the index of the last path separator (handles both Unix and Windows)
    int sepIdx = indexOfLastSeparator(filename);

    // Ensure that there is no separator after the last dot (i.e., dot belongs to the filename)
    return (sepIdx < dotIdx) ? dotIdx : -1;
}

public boolean isExpired(long timestamp, long expiredThreshold) {
    try {
        // If the threshold is non-positive, the metric should not expire.
        if (expiredThreshold <= 0) {
            return false;
        }
        long currentTime = System.currentTimeMillis();
        // A future timestamp indicates the metric is still fresh.
        if (timestamp > currentTime) {
            return false;
        }
        // Expire if the age of the metric exceeds the threshold.
        return (currentTime - timestamp) > expiredThreshold;
    } catch (Exception e) {
        // In the unlikely event of an exception, default to not expiring.
        return false;
    }
}

public boolean isExpired(long timestamp, long expiredThreshold) {
    // Validate inputs
    if (expiredThreshold <= 0) {
        // Non-positive threshold cannot expire anything
        return false;
    }
    // If timestamp is non-positive, cannot determine expiry safely
    if (timestamp <= 0) {
        return false;
    }
    try {
        long currentTime = System.currentTimeMillis();
        // Check for overflow (unlikely but safe)
        long elapsed = currentTime - timestamp;
        if (elapsed < 0) {
            // System clock moved backwards or timestamp in future
            return false;
        }
        return elapsed > expiredThreshold;
    } catch (Exception e) {
        // In case of any unforeseen error, default to not expired
        return false;
    }
}

public boolean isExpired(long timestamp, long expiredThreshold) {
    try {
        if (expiredThreshold <= 0) {
            return false;
        }
        if (timestamp < 0) {
            return false;
        }
        long now = System.currentTimeMillis();
        long elapsed = now - timestamp;
        return elapsed > expiredThreshold;
    } catch (Exception e) {
        return false;
    }
}

public boolean isExpired(long timestamp, long expiredThreshold) {
    // Validate input
    if (expiredThreshold <= 0) {
        throw new IllegalArgumentException("expiredThreshold must be a positive value");
    }
    if (timestamp < 0) {
        throw new IllegalArgumentException("timestamp cannot be negative");
    }
    long currentTime = System.currentTimeMillis();
    // If the current time has surpassed the point at which the entry should expire
    return currentTime >= timestamp + expiredThreshold;
}

public boolean isExpired(long timestamp, long expiredThreshold) {
    // Validate the expiration threshold - it should not be negative
    if (expiredThreshold < 0) {
        throw new IllegalArgumentException("expiredThreshold must be non-negative");
    }

    long currentTime = System.currentTimeMillis();

    // If the timestamp is in the future, consider it not yet expired
    if (currentTime < timestamp) {
        return false;
    }

    // Determine if the elapsed time since the timestamp exceeds the threshold
    return (currentTime - timestamp) > expiredThreshold;
}

