protected void append(LoggingEvent event) {
    // Guard against null event or client list
    if (event == null || clientStreams == null) {
        return;
    }

    String message = event.getRenderedMessage();
    // Append a line separator so each message is on its own line
    String line = message + System.lineSeparator();
    byte[] data;
    try {
        data = line.getBytes("UTF-8");
    } catch (java.io.UnsupportedEncodingException e) {
        // Fallback to platform default if UTF-8 is somehow unsupported
        data = line.getBytes();
    }

    // Synchronize on the collection of client streams to avoid concurrent modification
    Object sync = clientStreams;
    synchronized (sync) {
        java.util.Iterator<java.io.OutputStream> it = clientStreams.iterator();
        while (it.hasNext()) {
            java.io.OutputStream out = it.next();
            try {
                out.write(data);
                out.flush();
            } catch (java.io.IOException e) {
                // If writing to a client fails, close the stream and remove it
                try {
                    out.close();
                } catch (java.io.IOException ignored) {
                }
                it.remove();
                // Optionally, log the exception so the failure is visible
                // (Assuming a logger named 'log' is available)
                if (log != null) {
                    log.warn("Failed to send log message to a client; stream removed.", e);
                }
            }
        }
    }
}

protected void append(LoggingEvent event) {
    // Guard against null event
    if (event == null) {
        return;
    }

    // Convert the event into a string.  If the formatting fails, fall back to the raw message.
    String msg = event.getFormattedMessage();
    if (msg == null) {
        msg = event.getMessage() != null ? event.getMessage().toString() : "";
    }

    // Take a snapshot of the connected clients to avoid ConcurrentModification issues.
    List<Client> snapshot;
    synchronized (connectedClients) {
        snapshot = new ArrayList<>(connectedClients);
    }

    // Send the log message to each client.  Failures result in removal of the broken client.
    for (Client client : snapshot) {
        if (client == null) {
            continue;
        }
        try {
            client.write(msg);
        } catch (Exception e) {
            // Attempt to close the client safely before removal.
            try {
                client.close();
            } catch (Exception ignored) {
            }
            synchronized (connectedClients) {
                connectedClients.remove(client);
            }
        }
    }
}

protected void append(LoggingEvent event) {
    // Guard against null event
    if (event == null) {
        return;
    }
    // Retrieve the formatted message, providing a fallback if formatting fails
    String message;
    try {
        message = event.getFormattedMessage();
    } catch (Exception e) {
        message = "Logging error: unable to format message - " + e.getClass().getSimpleName() + ": " + e.getMessage();
    }
    if (message == null) {
        return; // nothing to send
    }

    // Assume a collection of client writers is maintained in the class
    // Avoid NPE if the collection hasn't been initialized
    if (clientWriters == null) {
        return;
    }

    // Send the message to each connected client, handling individual failures
    for (PrintWriter client : clientWriters) {
        if (client == null) {
            continue;
        }
        try {
            client.println(message);
            client.flush();
        } catch (Exception ex) {
            // Log the error locally (or ignore) – do not disrupt other clients
        }
    }
}

protected void append(LoggingEvent event) {
    if (event == null) {
        return;
    }

    // Get the rendered message from the event.  If it is null we simply use an empty string.
    String message = event.getRenderedMessage();
    if (message == null) {
        message = "";
    }

    // Iterate over all connected clients and write the message to each one.
    // Any client that is closed or encounters an exception while receiving the message
    // will be removed from the collection.
    // The collection is assumed to be thread‑safe or accessed under a synchronized block.
    try {
        Iterator<Socket> it = clients.iterator(); // clients is a collection of java.net.Socket
        while (it.hasNext()) {
            Socket client = it.next();
            try {
                // Skip clients that are no longer connected.
                if (client.isClosed() || !client.isConnected()) {
                    it.remove();
                    continue;
                }
                OutputStream out = client.getOutputStream();
                out.write(message.getBytes()); // platform default charset
                out.flush();
            } catch (IOException e) {
                // Remove misbehaving clients and close the socket.
                it.remove();
                try {
                    client.close();
                } catch (IOException ex) {
                    // ignore
                }
            }
        }
    } catch (Exception e) {
        // In an unlikely event that iterating over the collection fails, capture it.
        // Logging or recovery logic could be placed here if desired.
    }
}

protected void append(LoggingEvent event) {
    if (event == null) {
        return;
    }
    String message = event.getFormattedMessage();
    if (connectedClients == null || connectedClients.isEmpty()) {
        return;
    }
    for (Client client : connectedClients) {
        try {
            client.write(message);
        } catch (Exception ex) {
            // If a client fails, log to standard error and continue
            System.err.println("Failed to send log to client: " + ex.getMessage());
        }
    }
}

