private void checkIfPackedField() throws IOException {
    // The wire type is stored in the lower three bits of the last read tag.
    int wireType = currentTag & 0x07;
    // In the protobuf encoding, a repeated primitive field can be packed
    // by using a length-delimited field (wire type == 2).  If the field
    // descriptor indicates that this field is repeated and the wire type
    // matches, we treat the following length-delimited block as packed
    // data and update the internal parser state accordingly.
    if (isRepeated && wireType == 2) { // 2 == LENGTH_DELIMITED
        // Mark that we are now reading a packed field.
        isPacked = true;
        // Read the length of the packed region and store the end position.
        int packedLen = readRawVarint32();
        packedEnd = currentPos + packedLen;
    } else {
        // Not a packed field; ensure packed state is cleared.
        isPacked = false;
    }
}

private void checkIfPackedField() throws IOException {
    // The most recently read tag is stored in the inherited field 'lastTag'.
    int wireType = lastTag & 0x7; // Extract the wire type from the tag.
    if (wireType == 2) { // Wire type LENGTH_DELIMITED indicates a potential packed field.
        // Read the length of the packed data and set a new parser limit so that only
        // the packed bytes are read for this field.  The remaining data will be
        // returned to the normal parsing flow once this limit is released.
        int length = readRawVarint32();
        pushLimit(length);
    }
    // If the wire type is not LENGTH_DELIMITED, we simply return; no special
    // handling is required for non-packed fields.
}

private void checkIfPackedField() throws IOException {
    // Attempt to set a flag indicating that a packed repeated field is being read.
    // Many Protobuf implementations use a boolean field such as "packed_", "isPacked",
    // "readingPacked", or "isReadingPacked".  We try those names via reflection
    // and update the field if it exists.
    String[] potentialFieldNames = {
        "packed_",
        "isPacked",
        "readingPacked",
        "isReadingPacked"
    };
    for (String name : potentialFieldNames) {
        try {
            java.lang.reflect.Field f = this.getClass().getDeclaredField(name);
            if (f.getType() == boolean.class) {
                f.setAccessible(true);
                boolean current = f.getBoolean(this);
                if (!current) {
                    f.setBoolean(this, true);
                }
                break; // flag found and updated; no need to check others
            }
        } catch (NoSuchFieldException | IllegalAccessException ignored) {
            // Continue to next possible name
        }
    }
    // If no matching field exists, this method silently does nothing,
    // preserving existing behaviour while avoiding unchecked exceptions.
}

private void checkIfPackedField() throws IOException {
    // Packed repeated fields are encoded as a length‑delimited field that contains
    // a concatenated stream of the raw values. Detect this by checking that the
    // current tag has a length‑delimited wire type and that we are not already
    // processing a packed field. If it is packed, read the length prefix,
    // set a new input limit to confine reads to the packed data, and update
    // internal state to indicate that we are inside a packed field.
    if (!packed_) {
        int wireType = lastTag_ & 0x07;
        if (wireType == com.google.protobuf.WireFormat.WIRETYPE_LENGTH_DELIMITED) {
            int length = cachedInput_.readRawVarint32();
            long oldLimit = cachedInput_.pushLimit(length);
            packedFieldNumber_ = lastTag_ >>> 3;
            packedBytesLimit_ = (int) oldLimit;
            packed_ = true;
        }
    }
}

private void checkIfPackedField() throws IOException {
    // The packed repeated fields in protobuf are encoded as a length-delimited
    // field (wire type 2). We determine whether the current tag corresponds
    // to such a field and, if so, record the end position of the packed block
    // so that subsequent reads can treat it appropriately.
    // It is assumed that the class contains the following fields that are
    // used by this method: `tag`, `pos`, `limit`, `isPacked`, and
    // `packedEnd`.  The method `readRawVarint32()` is used to read a varint.
    //
    // This implementation is defensive: it checks for negative lengths
    // and ensures that the declared length does not exceed the remaining
    // bytes in the buffer.  If the checks fail, an IOException is thrown.

    // Check that a tag has been read; if not, we cannot proceed.
    // The tag is expected to contain both the field number and
    // the wire type in its lowest three bits.
    if (tag == 0) {
        // No tag has been read; this is an internal error.
        throw new IOException("No tag read before checking packed field");
    }

    // Extract the wire type from the tag.
    final int wireType = tag & 0x7;
    if (wireType != 2) {
        // Not a length-delimited field, so packed fields are not applicable.
        return;
    }

    // The field is length-delimited; read the length prefix.
    int length = readRawVarint32();
    if (length < 0) {
        throw new IOException("Negative packed field length");
    }

    // Verify that the packed data fits within the remaining buffer.
    if (length > limit - pos) {
        throw new IOException("Packed field truncated: declared length " +
                               length + " exceeds remaining bytes");
    }

    // Update the internal state to indicate that a packed block is being
    // read.  Subsequent read methods will use `packedEnd` to determine
    // when the packed block ends.
    isPacked = true;
    packedEnd = pos + length;
}

public int readTag() throws IOException {
    try {
        int tag = readRawVarint32();
        // In protocol buffers a tag of 0 is reserved for end-of-message
        // and should be treated as the end of the input.
        return (tag != 0) ? tag : 0;
    } catch (EOFException e) {
        // Reached end of the stream; no more tags
        return 0;
    }
}

