public int readTag() throws IOException {
    // Attempt to read the first byte of the varint-encoded tag.
    int firstByte = in.read();
    if (firstByte == -1) {
        // End of input stream: return zero to indicate EOF.
        return 0;
    }

    // Decode the varint. If the most significant bit is clear,
    // the tag fits in one byte.
    int result = firstByte & 0x7F;
    if ((firstByte & 0x80) == 0) {
        return result;
    }

    // Multi-byte varint: read subsequent bytes.
    int shift = 7;
    while (true) {
        int nextByte = in.read();
        if (nextByte == -1) {
            // Unexpected EOF while reading a multi-byte tag.
            throw new IOException("Truncated input: unexpected end of stream while reading tag");
        }
        result |= (nextByte & 0x7F) << shift;
        if ((nextByte & 0x80) == 0) {
            break;
        }
        shift += 7;
        if (shift > 35) {
            // Exceeds the maximum size for a 32-bit varint.
            throw new IOException("Malformed Varint: tag too large");
        }
    }

    return result;
}

public int readTag() throws IOException {
    int result = 0;
    // Read up to 5 bytes for a field tag (varint32).
    for (int shift = 0; shift < 35; shift += 7) {
        int b = in.read(); // 'in' is the input stream of the parser
        if (b == -1) {
            // End‑of‑file reached – signal the tag is finished.
            return 0;
        }
        result |= (b & 0x7F) << shift;
        if ((b & 0x80) == 0) {
            // This byte has the high bit cleared: tag parse complete.
            return result;
        }
    }
    // Too many bytes – the varint is malformed.
    throw new IOException("Malformed tag: input too long");
}

