    if (byteValue1 < -128 || byteValue1 > 127 || byteValue2 < -128 || byteValue2 > 127) {
        throw new IllegalArgumentException(
            "byte values must be within the signed byte range -128 to 127");
    }
    // Ensure capacity for two additional bytes
    int required = pos + 2;
    if (required > buffer.length) {
        int newSize = Math.max(buffer.length * 2, required);
        byte[] newBuffer = new byte[newSize];
        System.arraycopy(buffer, 0, newBuffer, 0, pos);
        buffer = newBuffer;
    }
    buffer[pos++] = (byte) byteValue1;
    buffer[pos++] = (byte) byteValue2;
    return this;
}

