private String buildContentRange(){
    try{
        java.lang.reflect.Field startField=null, endField=null, totalField=null;
        // Attempt to find start field
        for(String name: new String[]{"start","rangeStart","bytesStart"}){
            try{
                startField=this.getClass().getDeclaredField(name);
                startField.setAccessible(true);
                break;
            }catch(NoSuchFieldException ignored){}
        }
        // Attempt to find end field
        for(String name: new String[]{"end","rangeEnd","bytesEnd"}){
            try{
                endField=this.getClass().getDeclaredField(name);
                endField.setAccessible(true);
                break;
            }catch(NoSuchFieldException ignored){}
        }
        // Attempt to find total length field
        for(String name: new String[]{"total","contentLength","length","fileLength","totalLength"}){
            try{
                totalField=this.getClass().getDeclaredField(name);
                totalField.setAccessible(true);
                break;
            }catch(NoSuchFieldException ignored){}
        }
        if(startField==null || endField==null || totalField==null) return null;
        Object sObj=startField.get(this);
        Object eObj=endField.get(this);
        Object tObj=totalField.get(this);
        long start = sObj instanceof Number ? ((Number)sObj).longValue() : Long.parseLong(sObj.toString());
        long end   = eObj instanceof Number ? ((Number)eObj).longValue() : Long.parseLong(eObj.toString());
        long total = tObj instanceof Number ? ((Number)tObj).longValue() : Long.parseLong(tObj.toString());
        return "bytes "+start+"-"+end+"/"+total;
    }catch(Exception e){
        return null;
    }
}

private String buildContentRange() {
    // The media range must be non‑negative and the end cannot be before the start.
    if (rangeStart < 0 || rangeEnd < rangeStart) {
        throw new IllegalStateException("Invalid byte range: start=" + rangeStart + ", end=" + rangeEnd);
    }
    // totalSize may be unknown (e.g., streaming upload). In that case use '*' placeholder.
    if (totalSize <= 0) {
        return String.format("bytes %d-%d/*", rangeStart, rangeEnd);
    }
    return String.format("bytes %d-%d/%d", rangeStart, rangeEnd, totalSize);
}

private String buildContentRange(){
    try{
        Class<?> cls = this.getClass();
        Long startVal = null;
        Long lengthVal = null;
        Long sizeVal = null;
        // Inspect all fields for possible values
        for(java.lang.reflect.Field f : cls.getDeclaredFields()){
            String name = f.getName();
            f.setAccessible(true);
            Object value = f.get(this);
            if(value instanceof Number){
                Number num = (Number)value;
                if(name.equalsIgnoreCase("contentstart") || name.equalsIgnoreCase("start") || name.equalsIgnoreCase("rangeStart")){
                    startVal = num.longValue();
                }else if(name.equalsIgnoreCase("contentlength") || name.equalsIgnoreCase("length") || name.equalsIgnoreCase("contentlen") || name.equalsIgnoreCase("rangeEnd")){
                    // If 'rangeEnd' might represent end rather than length, handle only when both start and end available
                    if(name.equalsIgnoreCase("rangeEnd") && startVal != null){
                        // We already captured end via start+length-1 logic later
                        lengthVal = null; // ignore
                    }else{
                        lengthVal = num.longValue();
                    }
                }else if(name.equalsIgnoreCase("contentsize") || name.equalsIgnoreCase("size") || name.equalsIgnoreCase("totalsize") || name.equalsIgnoreCase("totalSize")){
                    sizeVal = num.longValue();
                }
            }
        }
        // If we couldn't find all required values, return null
        if(startVal == null || lengthVal == null || sizeVal == null){
            return null;
        }
        // Validate values
        if(startVal < 0 || lengthVal <= 0 || sizeVal <= 0){
            return null;
        }
        long end = startVal + lengthVal - 1;
        if(end >= sizeVal){
            end = sizeVal - 1;
        }
        return String.format("bytes %d-%d/%d", startVal, end, sizeVal);
    }catch(Exception e){
        // Any reflection or arithmetic issue results in null
        return null;
    }
}

private String buildContentRange(){
    try {
        long start = -1;
        long end = -1;
        long total = -1;
        Class<?> cls = this.getClass();

        // Attempt to find start value
        for (String name : new String[]{ "rangeStart", "start", "startByte" }) {
            try {
                java.lang.reflect.Field f = cls.getDeclaredField(name);
                f.setAccessible(true);
                Object val = f.get(this);
                if (val instanceof Number) {
                    start = ((Number) val).longValue();
                    break;
                }
            } catch (NoSuchFieldException ignored) { }
        }

        // Attempt to find end value
        for (String name : new String[]{ "rangeEnd", "end", "endByte" }) {
            try {
                java.lang.reflect.Field f = cls.getDeclaredField(name);
                f.setAccessible(true);
                Object val = f.get(this);
                if (val instanceof Number) {
                    end = ((Number) val).longValue();
                    break;
                }
            } catch (NoSuchFieldException ignored) { }
        }

        // Attempt to find total size
        for (String name : new String[]{ "totalSize", "contentLength", "size" }) {
            try {
                java.lang.reflect.Field f = cls.getDeclaredField(name);
                f.setAccessible(true);
                Object val = f.get(this);
                if (val instanceof Number) {
                    total = ((Number) val).longValue();
                    break;
                }
            } catch (NoSuchFieldException ignored) { }
        }

        if (start >= 0 && end >= start && total > 0) {
            return "bytes " + start + "-" + end + "/" + total;
        }
        // If values are not meaningful, return null or empty string
        return null;
    } catch (Exception e) {
        // In case of any unexpected error, return null
        return null;
    }
}

public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
    if (file == null) {
        throw new IllegalArgumentException("file cannot be null");
    }
    if (!file.exists() || !file.isFile()) {
        throw new FileNotFoundException("File does not exist: " + file);
    }
    // Assume there is a helper that parses all snapshots from the file.
    List<ThreadSnapshot> allSnapshots = parseFromFile(file);
    List<ThreadSnapshot> result = new ArrayList<>();

    if (timeRanges == null || timeRanges.isEmpty() || allSnapshots == null || allSnapshots.isEmpty()) {
        return result; // No data or no ranges, return empty list
    }

    for (ThreadSnapshot ts : allSnapshots) {
        long timestamp;
        try {
            timestamp = ts.getTimestamp();
        } catch (Exception e) {
            // If the snapshot doesn't expose its timestamp, skip it
            continue;
        }
        for (ProfileAnalyzeTimeRange tr : timeRanges) {
            if (tr == null) continue;
            long start = tr.getStartTime();
            long end = tr.getEndTime();
            if (start <= timestamp && timestamp <= end) {
                result.add(ts);
                break;
            }
        }
    }
    return result;
}

public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
    List<ThreadSnapshot> result = new ArrayList<>();
    if (file == null || !file.exists() || timeRanges == null || timeRanges.isEmpty()) {
        return result;
    }
    try (ObjectInputStream ois = new ObjectInputStream(new FileInputStream(file))) {
        @SuppressWarnings("unchecked")
        List<ThreadSnapshot> allSnapshots = (List<ThreadSnapshot>) ois.readObject();
        for (ThreadSnapshot ts : allSnapshots) {
            if (isWithinTimeRanges(ts, timeRanges)) {
                result.add(ts);
            }
        }
    } catch (ClassNotFoundException e) {
        // If the file was not in the expected serialized format, throw an IOException
        throw new IOException("Failed to deserialize thread snapshots from file: " + file.getAbsolutePath(), e);
    } catch (ClassCastException e) {
        // The file contents could not be cast to the expected type
        throw new IOException("Unexpected data type in snapshot file: " + file.getAbsolutePath(), e);
    }
    return result;
}

/**
 * Checks whether the given snapshot falls within any of the provided time ranges.
 */
private static boolean isWithinTimeRanges(ThreadSnapshot snapshot, List<ProfileAnalyzeTimeRange> ranges) {
    if (snapshot == null || ranges == null) {
        return false;
    }
    long timestamp = snapshot.getTimestamp(); // assumes ThreadSnapshot has getTimestamp()
    for (ProfileAnalyzeTimeRange range : ranges) {
        try {
            long start = range.getStartTime(); // assumes getStartTime() exists
            long end = range.getEndTime();     // assumes getEndTime() exists
            if (timestamp >= start && timestamp <= end) {
                return true;
            }
        } catch (Exception ignored) {
            // If the range does not provide the expected methods, skip it
        }
    }
    return false;
}

public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
    List<ThreadSnapshot> snapshots = new ArrayList<>();
    if (file == null || !file.exists() || !file.isFile()) {
        return snapshots;
    }
    try (FileInputStream fis = new FileInputStream(file);
         ObjectInputStream ois = new ObjectInputStream(fis)) {
        while (true) {
            Object obj;
            try {
                obj = ois.readObject();
            } catch (EOFException eof) {
                break;
            } catch (ClassNotFoundException cnf) {
                throw new IOException("Snapshot file contains unknown object type", cnf);
            }
            if (!(obj instanceof ThreadSnapshot)) {
                continue; // ignore unrelated objects
            }
            ThreadSnapshot snapshot = (ThreadSnapshot) obj;
            boolean inRange = true;
            if (timeRanges != null && !timeRanges.isEmpty()) {
                inRange = false;
                long tsTime;
                try {
                    tsTime = snapshot.getTimestamp();
                } catch (Throwable t) {
                    tsTime = -1; // if method is absent, treat as out of range
                }
                for (ProfileAnalyzeTimeRange range : timeRanges) {
                    if (range == null) {
                        continue;
                    }
                    long start = range.getStartTime();
                    long end = range.getEndTime();
                    if (tsTime >= start && tsTime <= end) {
                        inRange = true;
                        break;
                    }
                }
            }
            if (inRange) {
                snapshots.add(snapshot);
            }
        }
    }
    return snapshots;
}

public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
    List<ThreadSnapshot> snapshots = new ArrayList<>();
    if (file == null || !file.exists() || !file.isFile()) {
        throw new IOException("File is null or does not exist");
    }
    if (timeRanges == null || timeRanges.isEmpty()) {
        // No time ranges to filter on, return empty list
        return snapshots;
    }
    try (BufferedReader br = new BufferedReader(new FileReader(file))) {
        String line;
        Pattern pattern = Pattern.compile("(\\d+)");
        while ((line = br.readLine()) != null) {
            if (line.trim().isEmpty()) continue;
            Matcher matcher = pattern.matcher(line);
            if (!matcher.find()) continue;
            long timestamp;
            try {
                timestamp = Long.parseLong(matcher.group(1));
            } catch (NumberFormatException nfe) {
                continue;
            }
            boolean inRange = false;
            for (ProfileAnalyzeTimeRange range : timeRanges) {
                try {
                    Method getStart = range.getClass().getMethod("getStartTime");
                    Method getEnd = range.getClass().getMethod("getEndTime");
                    long start = (Long) getStart.invoke(range);
                    long end = (Long) getEnd.invoke(range);
                    if (timestamp >= start && timestamp <= end) {
                        inRange = true;
                        break;
                    }
                } catch (Exception e) {
                    // If methods not found or invocation fails, skip this range
                }
            }
            if (!inRange) continue;
            try {
                // Attempt to use a static parse method
                Method parseMethod = ThreadSnapshot.class.getMethod("parseFromString", String.class);
                ThreadSnapshot snapshot = (ThreadSnapshot) parseMethod.invoke(null, line);
                if (snapshot != null) {
                    snapshots.add(snapshot);
                    continue;
                }
            } catch (Exception e) {
                // Ignore failures
            }
            try {
                // Fallback: try constructor with long timestamp
                Constructor<?> ctor = ThreadSnapshot.class.getConstructor(long.class);
                ThreadSnapshot snapshot = (ThreadSnapshot) ctor.newInstance(timestamp);
                snapshots.add(snapshot);
            } catch (Exception e) {
                // If constructor not found, skip this line
            }
        }
    }
    return snapshots;
}

public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
    if (file == null) {
        throw new IOException("File argument is null");
    }
    if (!file.exists() || !file.isFile()) {
        throw new IOException("File does not exist: " + file.getAbsolutePath());
    }
    if (timeRanges == null || timeRanges.isEmpty()) {
        return new java.util.ArrayList<>();
    }
    java.util.List<ThreadSnapshot> result = new java.util.ArrayList<>();
    java.io.BufferedReader br = null;
    try {
        br = new java.io.BufferedReader(new java.io.FileReader(file));
        String line;
        while ((line = br.readLine()) != null) {
            line = line.trim();
            if (line.isEmpty()) {
                continue;
            }
            try {
                ThreadSnapshot ts = new com.fasterxml.jackson.databind.ObjectMapper().readValue(line, ThreadSnapshot.class);
                // Assume ProfileAnalyzeTimeRange has method contains(long millis)
                for (ProfileAnalyzeTimeRange range : timeRanges) {
                    try {
                        java.lang.reflect.Method containsMethod = range.getClass().getMethod("contains", long.class);
                        Object res = containsMethod.invoke(range, ts.getTimestamp());
                        if (res instanceof Boolean && (Boolean) res) {
                            result.add(ts);
                            break;
                        }
                    } catch (NoSuchMethodException e) {
                        // fallback: assume range has start and end fields
                        java.lang.reflect.Field startField = range.getClass().getField("start");
                        java.lang.reflect.Field endField = range.getClass().getField("end");
                        long start = startField.getLong(range);
                        long end = endField.getLong(range);
                        if (ts.getTimestamp() >= start && ts.getTimestamp() <= end) {
                            result.add(ts);
                            break;
                        }
                    }
                }
            } catch (Exception e) {
                // if any parsing error occurs, wrap into IOException
                throw new IOException("Failed to parse line into ThreadSnapshot: " + line, e);
            }
        }
    } finally {
        if (br != null) {
            try {
                br.close();
            } catch (Exception ignored) {
            }
        }
    }
    return result;
}
